# БЛОК: analysis.api_reference.py  
# ════════════════════════════════════════════════════════════════════════════
__frame__()
"""
TRIVORTEX MASTER — автоматический генератор справочника API.

Обходит все публичные модули пакета через inspect/ast и строит:

  * справочник функций/классов: сигнатуры, docstring-первая строка,
    модуль-источник;
  * статистику покрытия документацией;
  * Markdown-справочник (docs/API.md) и данные для пункта меню;
  * оглавление по пакетам (core/lab/render/realism/reports/analysis).

Гарантированно честный: то, что в справочнике, существует в коде
(генерация из ast, а не рукописный список).
"""


import ast
import os
from typing import Any

ROOT = _PKG_ROOT
PACKAGES = ("core", "lab", "render", "realism", "reports", "analysis")
ENTRY_FILES = ("trivortex_master.py",)


def _first_line(doc: str | None) -> str:
    """Do first line for doc and return the result."""
    if not doc:
        return ""
    for line in doc.strip().splitlines():
        s = line.strip()
        if s:
            return s
    return ""


def _format_signature(node: ast.FunctionDef | ast.AsyncFunctionDef) -> str:
    """Signature string without annotations (compact)."""
    args = []
    defaults_offset = len(node.args.args) - len(node.args.defaults)
    for i, a in enumerate(node.args.args):
        s = a.arg
        di = i - defaults_offset
        if di >= 0 and node.args.defaults:
            try:
                s += "=" + ast.unparse(node.args.defaults[di])
            except Exception:
                s += "=…"
        args.append(s)
    if node.args.vararg:
        args.append("*" + node.args.vararg.arg)
    for a, d in zip(node.args.kwonlyargs, node.args.kw_defaults):
        s = a.arg
        if d is not None:
            try:
                s += "=" + ast.unparse(d)
            except Exception:
                s += "=…"
        args.append(s)
    if node.args.kwarg:
        args.append("**" + node.args.kwarg.arg)
    return f"{node.name}({', '.join(args)})"


def scan_module(path: str, package: str) -> dict[str, Any]:
    """Scan one file: functions/classes/methods."""
    rel = os.path.relpath(path, ROOT)
    info: dict[str, Any] = dict(
        module=rel, package=package, functions=[], classes=[], documented=0, total=0, lines=0
    )
    try:
        src = open(path, encoding="utf-8").read()
    except OSError:
        return info
    info["lines"] = src.count("\n") + 1
    try:
        tree = ast.parse(src)
    except SyntaxError:
        return info

    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            if node.name.startswith("_"):
                continue
            doc = _first_line(ast.get_docstring(node))
            info["functions"].append(
                dict(
                    name=node.name, signature=_format_signature(node), doc=doc, documented=bool(doc)
                )
            )
            info["total"] += 1
            info["documented"] += 1 if doc else 0
        elif isinstance(node, ast.ClassDef):
            doc = _first_line(ast.get_docstring(node))
            methods = []
            for sub in node.body:
                if isinstance(
                    sub, (ast.FunctionDef, ast.AsyncFunctionDef)
                ) and not sub.name.startswith("_"):
                    mdoc = _first_line(ast.get_docstring(sub))
                    methods.append(
                        dict(
                            name=sub.name,
                            signature=_format_signature(sub),
                            doc=mdoc,
                            documented=bool(mdoc),
                        )
                    )
                    info["total"] += 1
                    info["documented"] += 1 if mdoc else 0
            info["classes"].append(
                dict(name=node.name, doc=doc, documented=bool(doc), methods=methods)
            )
            info["total"] += 1
            info["documented"] += 1 if doc else 0
    return info


def scan_all() -> list[dict[str, Any]]:
    """Scan entire package."""
    out = []
    for pkg in PACKAGES:
        pdir = os.path.join(ROOT, pkg)
        if not os.path.isdir(pdir):
            continue
        for base, dirs, files in os.walk(pdir):
            dirs[:] = [d for d in dirs if d != "__pycache__"]
            for fn in sorted(files):
                if fn.endswith(".py") and fn != "__init__.py":
                    out.append(scan_module(os.path.join(base, fn), pkg))
    for entry in ENTRY_FILES:
        path = os.path.join(ROOT, entry)
        if os.path.isfile(path):
            out.append(scan_module(path, "entry"))
    return out


# ═══════════════════════════════════════════════════════════════════════════
# Экспорт в Markdown
# ═══════════════════════════════════════════════════════════════════════════
def to_markdown(infos: list[dict[str, Any]], version: str = "2.0.0") -> str:
    """Markdown API reference."""
    lines = [f"# TRIVORTEX MASTER v{version} — справочник API", ""]
    lines.append("*Автогенерация из AST: всё, что здесь описано, " "существует в коде.*")
    lines.append("")
    total_f = sum(len(i["functions"]) for i in infos)
    total_c = sum(len(i["classes"]) for i in infos)
    total_doc = sum(i["documented"] for i in infos)
    total_def = sum(i["total"] for i in infos)
    lines.append(
        f"**{len(infos)} модулей · {total_c} классов · "
        f"{total_f} функций · документировано "
        f"{total_doc}/{total_def} "
        f"({100 * total_doc / max(total_def, 1):.0f}%)**"
    )
    lines.append("")
    # оглавление по пакетам
    lines.append("## Оглавление")
    lines.append("")
    by_pkg: dict[str, list] = {}
    for i in infos:
        by_pkg.setdefault(i["package"], []).append(i)
    for pkg in sorted(by_pkg):
        lines.append(
            f"- **{pkg}**: " + ", ".join(f"`{os.path.basename(m['module'])}`" for m in by_pkg[pkg])
        )
    lines.append("")
    # тело
    for pkg in sorted(by_pkg):
        lines.append(f"## Пакет `{pkg}`")
        lines.append("")
        for mod in by_pkg[pkg]:
            lines.append(f"### `{mod['module']}`")
            lines.append("")
            if mod["classes"]:
                lines.append("**Классы:**")
                lines.append("")
                for cls in mod["classes"]:
                    doc = f" — {cls['doc']}" if cls["doc"] else ""
                    lines.append(f"- `{cls['name']}`{doc}")
                    for m in cls["methods"]:
                        mdoc = f" — {m['doc']}" if m["doc"] else ""
                        lines.append(f"  - `{m['signature']}`{mdoc}")
                lines.append("")
            if mod["functions"]:
                lines.append("**Функции:**")
                lines.append("")
                for f in mod["functions"]:
                    doc = f" — {f['doc']}" if f["doc"] else ""
                    lines.append(f"- `{f['signature']}`{doc}")
                lines.append("")
    return "\n".join(lines)


def write_api_doc(output: str | None = None, version: str = "2.0.0") -> str:
    """Generate docs/API.md."""
    infos = scan_all()
    md = to_markdown(infos, version)
    output = output or os.path.join(ROOT, "docs", "API.md")
    os.makedirs(os.path.dirname(output), exist_ok=True)
    with open(output, "w", encoding="utf-8") as fh:
        fh.write(md)
    return output


def stats() -> dict[str, Any]:
    """Summary for "About the suite" menu."""
    infos = scan_all()
    total_f = sum(len(i["functions"]) for i in infos)
    total_c = sum(len(i["classes"]) for i in infos)
    total_doc = sum(i["documented"] for i in infos)
    total_def = sum(i["total"] for i in infos)
    return dict(
        modules=len(infos),
        classes=total_c,
        functions=total_f,
        documented=total_doc,
        total_definitions=total_def,
        docstring_coverage=total_doc / max(total_def, 1),
        lines=sum(i["lines"] for i in infos),
    )


def self_check_api_reference() -> dict:
    """Reference generated and contains actual functions."""
    path = write_api_doc()
    text = open(path, encoding="utf-8").read()
    st = stats()
    # выборочная проверка: ключевые функции реально в справочнике
    must_have = [
        "theorem31",
        "run_simulation",
        "write_png",
        "lzw_compress",
        "kepler_E",
        "lyapunov_exponent",
        "generate_reports",
    ]
    missing = [m for m in must_have if m not in text]
    return dict(
        path=path,
        size_bytes=os.path.getsize(path),
        **st,
        missing_samples=missing,
        ok=(not missing and st["modules"] >= 30 and st["functions"] >= 250),
    )


if _MODULE_MAIN:
    import json

    print(json.dumps(self_check_api_reference(), ensure_ascii=False, indent=1, default=str))

__link__("analysis.api_reference", [('annotations', 'annotations'), ('ast', 'ast'), ('os', 'os'), ('re', 're'), ('Any', 'Any'), ('ROOT', 'ROOT'), ('PACKAGES', 'PACKAGES'), ('ENTRY_FILES', 'ENTRY_FILES'), ('_first_line', '_first_line'), ('_format_signature', '_format_signature'), ('scan_module', 'scan_module'), ('scan_all', 'scan_all'), ('to_markdown', 'to_markdown'), ('write_api_doc', 'write_api_doc'), ('stats', 'stats'), ('self_check', 'self_check_api_reference')])
# ════════════════════════════════════════════════════════════════════════════

# БЛОК: analysis.benchmark.py  
# ════════════════════════════════════════════════════════════════════════════
__frame__()
"""
TRIVORTEX MASTER — бенчмарк-комплекс: производительность всех подсистем.

Сценарии (каждый — время + контроль корректности):

  B1  интеграторы: RK4 vs leapfrog vs Yoshida4 (двухтеловая);
  B2  Barnes-Hut: построение дерева, сила, ускорение vs direct;
  B3  рендер: pure_raster кадр, raytracer кадр, ascii кадр;
  B4  PNG/GIF: кодирование кадра, LZW-сжатие;
  B5  вихревой движок: шаг N=7, интегралы;
  B6  MCMC: 2000 итераций на линейной модели;
  B7  отчёты: полный набор 7 форматов;
  B8  вейвлет CWT на 600 точках.

Итог — сводная таблица + JSON-протокол; сравнение с референсными
временами (пороги медленных регрессий задаются множителем).
"""


import json
import os
import sys
import time
from typing import Any

ROOT = _PKG_ROOT
if ROOT not in sys.path:
    sys.path.insert(0, ROOT)


class Bench:
    """One scenario: measurement + threshold."""

    def __init__(self, name: str, threshold_s: float | None = None):
        """Do Bench.  init for name, threshold_s and return the result."""
        self.name = name
        self.threshold = threshold_s
        self.elapsed = 0.0
        self.metrics: dict[str, Any] = {}
        self.passed = True
        self._t0 = 0.0

    def __enter__(self):
        """Handle Bench.  enter."""
        self._t0 = time.perf_counter()
        return self

    def __exit__(self, *exc):
        """Handle Bench.  exit."""
        self.elapsed = time.perf_counter() - self._t0
        if self.threshold is not None and self.elapsed > self.threshold:
            self.passed = False
        return False


def bench_integrators() -> Bench:
    """B1: two-body orbit, 1000 steps by each integrator."""
    b = Bench("B1 интеграторы", threshold_s=30.0)
    import math
    from lab.integrators import Leapfrog, Yoshida4, rk4_step

    G = 1.0

    def accel(pos, t):
        out = []
        for i in range(len(pos)):
            ax = ay = az = 0.0
            for j in range(len(pos)):
                if i == j:
                    continue
                dx = pos[j][0] - pos[i][0]
                dy = pos[j][1] - pos[i][1]
                dz = pos[j][2] - pos[i][2]
                r = math.sqrt(dx * dx + dy * dy + dz * dz) + 1e-12
                f = G / (r**3)
                ax += f * dx
                ay += f * dy
                az += f * dz
            out.append((ax, ay, az))
        return out

    def deriv(y, t):
        n = len(y) // 6
        out = [0.0] * len(y)
        for i in range(n):
            out[6 * i : 6 * i + 3] = y[6 * i + 3 : 6 * i + 6]
        acc = accel([tuple(y[6 * i : 6 * i + 3]) for i in range(n)], t)
        for i in range(n):
            out[6 * i + 3 : 6 * i + 6] = acc[i]
        return out

    v = math.sqrt(0.5)
    y0 = [-0.5, 0, 0, 0, -v, 0, 0.5, 0, 0, 0, v, 0]
    with b:
        t_rk4 = time.perf_counter()
        y = list(y0)
        for _ in range(500):
            y, _t = rk4_step(deriv, y, 0, 0.02)
        t_rk4 = time.perf_counter() - t_rk4
        t_lf = time.perf_counter()
        lf = Leapfrog(accel, 2)
        y = list(y0)
        for _ in range(500):
            y, _t = lf.step(y, 0, 0.02)
        t_lf = time.perf_counter() - t_lf
        t_yo = time.perf_counter()
        yo = Yoshida4(accel, 2)
        y = list(y0)
        for _ in range(500):
            y, _t = yo.step(y, 0, 0.02)
        t_yo = time.perf_counter() - t_yo
    b.metrics = dict(
        rk4_s=t_rk4, leapfrog_s=t_lf, yoshida4_s=t_yo, yoshida_slower=t_yo / max(t_lf, 1e-9)
    )
    b.passed = t_rk4 < 15 and t_lf < 10
    return b


def bench_barnes_hut() -> Bench:
    """B2: tree of 400 bodies."""
    b = Bench("B2 Barnes-Hut", threshold_s=25.0)
    from lab.nbody_tree import   benchmark

    with b:
        res = benchmark(n_bodies=400, seed=1)
    b.metrics = res
    b.passed = res["err_rms"] < 0.1
    return b


def bench_render() -> Bench:
    """B3: frames by all backends."""
    b = Bench("B3 рендер", threshold_s=25.0)
    with b:
        from render.pure_raster import render_bodies

        bodies = [
            dict(position=(0, 0, 0), radius=0.3, color="#FDB813"),
            dict(position=(1.2, 0.4, 0), radius=0.15, color="#4FD1C5"),
            dict(position=(-1, -0.5, 0.6), radius=0.12, color="#E8C766"),
        ]
        t0 = time.perf_counter()
        frame = render_bodies(bodies, width=320, height=240)
        t_pure = time.perf_counter() - t0
        # raytracer
        from render.raytracer import demo_scene, render_to_png, Camera

        t0 = time.perf_counter()
        render_to_png(
            demo_scene(), Camera(aspect=4 / 3), "/tmp/tv_bench_rt.png", width=100, height=75
        )
        t_ray = time.perf_counter() - t0
        # ascii
        from render.backend_ascii import render_ascii

        t0 = time.perf_counter()
        render_ascii(
            [dict(position=p["position"], radius=0.2, color=p["color"]) for p in bodies],
            width=60,
            height=18,
        )
        t_ascii = time.perf_counter() - t0
    b.metrics = dict(pure_s=t_pure, raytracer_s=t_ray, ascii_s=t_ascii)
    b.passed = frame is not None and t_ascii < 2.0
    return b


def bench_codecs() -> Bench:
    """B4: PNG and GIF encoding."""
    b = Bench("B4 PNG/GIF кодеки", threshold_s=30.0)
    with b:
        from render.png_codec import write_png

        px = bytearray()
        for y in range(180):
            for x in range(240):
                px += bytes([(x * y) % 256, x % 256, y % 256])
        t0 = time.perf_counter()
        write_png("/tmp/tv_bench.png", px, 240, 180)
        t_png = time.perf_counter() - t0
        from render.animator import write_gif

        frames = [
            bytes((i % 256 if (j // 8) % 2 else 0) for j in range(120 * 90)) for i in range(6)
        ]
        t0 = time.perf_counter()
        write_gif("/tmp/tv_bench.gif", frames, 120, 90, delay_cs=5)
        t_gif = time.perf_counter() - t0
    size_png = os.path.getsize("/tmp/tv_bench.png")
    size_gif = os.path.getsize("/tmp/tv_bench.gif")
    b.metrics = dict(png_s=t_png, gif_s=t_gif, png_bytes=size_png, gif_bytes=size_gif)
    b.passed = size_png > 1000 and size_gif > 500
    return b


def bench_vortex() -> Bench:
    """B5: vortex engine N=7, 200 steps."""
    b = Bench("B5 вихревой движок", threshold_s=20.0)
    with b:
        import math
        from core.config import from_profile
        from lab.body import Body
        from lab.physics import run_simulation
        from lab.scene import Scene

        cfg = from_profile("quick", n_steps=200, physics_engine="native_vortex")
        sc = Scene(cfg, name="bench_vortex")
        for k in range(7):
            phi = 2 * math.pi * k / 7
            sc.add_body(
                Body(
                    id=f"v{k}",
                    name=f"V{k}",
                    mass=1.0,
                    radius=0.02,
                    position=(math.cos(phi), math.sin(phi), 0),
                    circulation=1.0,
                    type="synthetic",
                    source="bench",
                )
            )
        sc.dt = 0.02
        sim = run_simulation(sc, n_steps=200)
    b.metrics = dict(energy_drift=sim["energy_drift_rel"], t_final=sc.t)
    b.passed = sim["energy_drift_rel"] < 1e-8
    return b


def bench_mcmc() -> Bench:
    """B6: MCMC 4×800 iterations."""
    b = Bench("B6 MCMC", threshold_s=60.0)
    with b:
        from analysis.mcmc import MetropolisSampler, gaussian_loglike, linear_model, flat_prior
        import random as _rnd

        rng = _rnd.Random(1)
        x = [i / 8.0 for i in range(40)]
        data = [1.5 + 0.8 * xi + rng.gauss(0, 0.15) for xi in x]

        def log_post(theta):
            lp = flat_prior(theta, [(-10, 10), (-10, 10)])
            if lp == float("-inf"):
                return lp
            return lp + gaussian_loglike(
                lambda th: linear_model(th, x), data, [0.15] * len(x), theta
            )

        t0 = time.perf_counter()
        for seed in range(4):
            s = MetropolisSampler(log_post, [1, 1], [0.1, 0.02], seed=seed)
            s.run(800, burn_in=200)
        t_mcmc = time.perf_counter() - t0
    b.metrics = dict(total_s=t_mcmc, chains=4, samples_per_chain=800)
    b.passed = t_mcmc < 55
    return b


def bench_reports() -> Bench:
    """B7: complete set of reports."""
    b = Bench("B7 отчёты 7 форматов", threshold_s=45.0)
    with b:
        from core.config import from_profile
        from lab.presets import build_preset
        from lab.physics import run_simulation
        from reports.engine import ReportData, generate_reports, validate_outputs

        sc = build_preset("earth_moon", from_profile("quick", n_steps=15))
        run_simulation(sc, n_steps=15)
        data = ReportData("Бенчмарк", scene=sc)
        data.fill_from_scene()
        written = generate_reports(
            data,
            "/tmp/tv_bench_reports",
            formats=["txt", "md", "html", "csv", "json", "docx", "pdf"],
        )
        problems = validate_outputs(written)
    b.metrics = dict(written=len(written), problems=problems)
    b.passed = not problems and len(written) == 7
    return b


def bench_wavelet() -> Bench:
    """B8: CWT Morlet at 600 points, 24 frequencies."""
    b = Bench("B8 вейвлет CWT", threshold_s=40.0)
    with b:
        import math as _m
        from analysis.wavelets import cwt_morlet

        dt = 0.01
        y = [_m.sin(2 * _m.pi * 3 * i * dt) for i in range(600)]
        freqs = [1 + 5 * i / 23.0 for i in range(24)]
        cwt = cwt_morlet(y, dt, freqs=freqs)
    b.metrics = dict(n_freqs=len(cwt["freqs"]), n_times=len(cwt["times"]))
    b.passed = len(cwt["freqs"]) == 24
    return b


ALL_BENCHES = [
    bench_integrators,
    bench_barnes_hut,
    bench_render,
    bench_codecs,
    bench_vortex,
    bench_mcmc,
    bench_reports,
    bench_wavelet,
]


def run_all_benchmark(only: list[str] | None = None) -> dict:
    """Run benchmarks; return protocol."""
    results = []
    for fn in ALL_BENCHES:
        b = fn()
        if only and b.name.split()[0] not in only:
            continue
        mark = "✓" if b.passed else "✗"
        print(
            f"  [{mark}] {b.name}: {b.elapsed:.2f} с "
            f"({', '.join(f'{k}={_fmt(v)}' for k, v in list(b.metrics.items())[:3])})"
        )
        results.append(
            dict(
                name=b.name,
                elapsed_s=b.elapsed,
                passed=b.passed,
                metrics=b.metrics,
                threshold_s=b.threshold,
            )
        )
    return dict(
        benches=results,
        total_s=sum(r["elapsed_s"] for r in results),
        passed=sum(1 for r in results if r["passed"]),
        total=len(results),
        all_pass=all(r["passed"] for r in results),
    )


def _fmt(v: Any) -> str:
    """Do fmt for v and return the result."""
    if isinstance(v, float):
        return f"{v:.3g}"
    return str(v)


def save_protocol(result: dict, path: str) -> None:
    """Save save protocol to disk (JSON)."""
    with open(path, "w", encoding="utf-8") as fh:
        json.dump(result, fh, ensure_ascii=False, indent=1, default=str)


if _MODULE_MAIN:
    protocol = run_all_benchmark()
    save_protocol(protocol, os.path.join(ROOT, "runs", "benchmark.json"))
    print(f"\nитог: {protocol['passed']}/{protocol['total']} за " f"{protocol['total_s']:.1f} с")

__link__("analysis.benchmark", [('annotations', 'annotations'), ('json', 'json'), ('os', 'os'), ('sys', 'sys'), ('time', 'time'), ('Any', 'Any'), ('ROOT', 'ROOT'), ('Bench', 'Bench'), ('bench_integrators', 'bench_integrators'), ('bench_barnes_hut', 'bench_barnes_hut'), ('bench_render', 'bench_render'), ('bench_codecs', 'bench_codecs'), ('bench_vortex', 'bench_vortex'), ('bench_mcmc', 'bench_mcmc'), ('bench_reports', 'bench_reports'), ('bench_wavelet', 'bench_wavelet'), ('ALL_BENCHES', 'ALL_BENCHES'), ('run_all', 'run_all_benchmark'), ('_fmt', '_fmt'), ('save_protocol', 'save_protocol')])
