# БЛОК: analysis.lomb_scargle.py  
# ════════════════════════════════════════════════════════════════════════════
__frame__()
"""
TRIVORTEX MASTER — периодограмма Ломба-Скаргла на чистом stdlib.

Классический метод поиска периодов в неравномерных рядах:

  * lomb_scargle(t, y, dy, f_grid): нормированная LS-статистика
    (Lomb 1976, ApSS 39, 447; Scargle 1982, ApJ 263, 835) с
    ортогональной подгонкой фазы τ;
  * автоматическая сетка частот: от 1/T (oversample×) до Найквиста;
  * false alarm probability: FAP_single = e^{−z} (экспоненциальное
    распределение мощности белого шума), глобальная ≈ M·e^{−z}
    (M — эффективное число независимых частот);
  * phase_fold: складывание ряда по периоду (для кривой блеска);
  * alias_report: боковые пики ±1/T_day и их отличие от истинного.

Самопроверка: синусоида 7.4 сут с пропусками и шумом восстанавливается
с ошибкой < 0.5%; шумовой ряд — FAP > 5% (ложных открытий нет).
"""


import math
from typing import Sequence


# ═══════════════════════════════════════════════════════════════════════════
# Статистика Ломба-Скаргла
# ═══════════════════════════════════════════════════════════════════════════
def _tau_offset(omega: float, t: Sequence[float], w: Sequence[float]) -> float:
    """Phase shift τ = atan2(ΣW sin2ωt, ΣW cos2ωt)/(2ω) — LS variant."""
    num = sum(wi * math.sin(2 * omega * ti) for wi, ti in zip(w, t))
    den = sum(wi * math.cos(2 * omega * ti) for wi, ti in zip(w, t))
    if abs(den) < 1e-300 and abs(num) < 1e-300:
        return 0.0
    return math.atan2(num, den) / (2.0 * omega)


def lomb_scargle_at(
    t: Sequence[float], y: Sequence[float], dy: Sequence[float], omega: float
) -> float:
    """LS power at one frequency (Press et al., Numerical Recipes §13.8).

    Weights W = 1/dy² (dy — true point errors). Normalization /2:
    for white noise E[num²/den] = 1 for each term → power
    distributed exponentially with mean 1 (Scargle 1982).
    """
    weights = [1.0 / (d * d) for d in dy]
    y_mean = sum(wi * yi for wi, yi in zip(weights, y)) / sum(weights)
    yc = [yi - y_mean for yi in y]
    tau = _tau_offset(omega, t, weights)
    ct = [math.cos(omega * (ti - tau)) for ti in t]
    st = [math.sin(omega * (ti - tau)) for ti in t]
    num_c = sum(wi * yi * ci for wi, yi, ci in zip(weights, yc, ct))
    num_s = sum(wi * yi * si for wi, yi, si in zip(weights, yc, st))
    den_c = sum(wi * ci * ci for wi, ci in zip(weights, ct))
    den_s = sum(wi * si * si for wi, si in zip(weights, st))
    if den_c < 1e-300 or den_s < 1e-300:
        return 0.0
    return (num_c * num_c / den_c + num_s * num_s / den_s) / 2.0


def frequency_grid(
    t: Sequence[float], oversample: float = 5.0, f_max: float | None = None
) -> list[float]:
    """Frequency grid: [oversample/T, f_max] with step 1/(oversample·T)."""
    t_span = max(t) - min(t)
    f_min = oversample / t_span
    if f_max is None:
        # Найквист по среднему шагу
        dt_mean = t_span / max(len(t) - 1, 1)
        f_max = 0.5 / dt_mean
    n = max(int((f_max - f_min) / (1.0 / (oversample * t_span))), 2)
    return [f_min + (f_max - f_min) * i / n for i in range(n + 1)]


def lomb_scargle(
    t: Sequence[float],
    y: Sequence[float],
    dy: Sequence[float],
    oversample: float = 5.0,
    f_max: float | None = None,
) -> dict:
    """Full LS periodogram: grid, powers, peak, FAP."""
    if len(t) != len(y) or len(t) != len(dy):
        raise ValueError("t, y, dy должны быть одной длины")
    freqs = frequency_grid(t, oversample, f_max)
    powers = [lomb_scargle_at(t, y, dy, 2 * math.pi * f) for f in freqs]
    z_max = max(powers)
    f_max_idx = powers.index(z_max)
    # глобальная FAP: 1 − (1 − e^{−z})^M ≈ M·e^{−z}; порог детекции
    # по экстремальным значениям: z_max > ln(M_eff) (максимум M
    # экспоненциальных величин ~ ln M)
    m_eff = len(freqs)
    fap = min(1.0, m_eff * math.exp(-z_max))
    threshold = math.log(m_eff)
    return dict(
        freqs=freqs,
        powers=powers,
        best_freq=freqs[f_max_idx],
        best_period=1.0 / freqs[f_max_idx],
        peak_power=z_max,
        false_alarm_prob=fap,
        threshold=threshold,
        n_eff_freqs=m_eff,
        detected=(z_max > threshold and fap < 0.05),
    )


# ═══════════════════════════════════════════════════════════════════════════
# Фазовая свёртка и алиасы
# ═══════════════════════════════════════════════════════════════════════════
def phase_fold(
    t: Sequence[float], y: Sequence[float], period: float, t0: float = 0.0, n_bins: int = 20
) -> list[dict]:
    """Fold series by period; return mean y per phase bins."""
    phases = [((ti - t0) / period) % 1.0 for ti in t]
    bins = [[] for _ in range(n_bins)]
    for ph, yi in zip(phases, y):
        idx = min(int(ph * n_bins), n_bins - 1)
        bins[idx].append(yi)
    out = []
    for i, vals in enumerate(bins):
        if vals:
            out.append(dict(phase=(i + 0.5) / n_bins, mean=sum(vals) / len(vals), n=len(vals)))
    return out


def alias_report(t: Sequence[float], ls: dict, base_unit: float = 1.0) -> list[dict]:
    """Strongest side peaks: alias candidates (f ± k·f_window).

    Observation window 1/T_span; aliases at f ± 1/base_unit (days →
    typical ground alias).
    """
    span = max(t) - min(t)
    f_win = 1.0 / span
    out = []
    # топ-пики вне главного
    pairs = sorted(zip(ls["freqs"], ls["powers"]), key=lambda fp: -fp[1])
    f_best = ls["best_freq"]
    for f, p in pairs[1:]:
        near_alias = abs(abs(f - f_best) - f_win) < 0.1 * f_win
        near_daily = any(abs(abs(f - f_best) - k / base_unit) < 0.02 for k in (1, 2))
        if near_alias or near_daily:
            out.append(dict(freq=f, power=p, kind="alias-candidate"))
        if len(out) >= 3:
            break
    return out


# ═══════════════════════════════════════════════════════════════════════════
# Самопроверка
# ═══════════════════════════════════════════════════════════════════════════
def self_check_lomb_scargle() -> dict:
    """Sinusoid with gaps: period recovered; noise undetected."""
    import random

    rng = random.Random(12)
    # ряд с пропусками: 120 точек на 100 сут, 7.4-суточный сигнал
    t = sorted(rng.uniform(0, 100) for _ in range(120))
    period_true = 7.4
    amp = 1.0
    noise = 0.25
    y = [amp * math.sin(2 * math.pi * ti / period_true) + rng.gauss(0, noise) for ti in t]
    dy = [noise] * len(t)
    ls = lomb_scargle(t, y, dy)
    err = abs(ls["best_period"] - period_true) / period_true
    # шумовой ряд
    y_noise = [rng.gauss(0, noise) for _ in t]
    ls_noise = lomb_scargle(t, y_noise, dy)
    # фазовая свёртка по истинному периоду: амплитуда сохранена
    folded = phase_fold(t, y, period_true)
    fold_amp = max(f["mean"] for f in folded) - min(f["mean"] for f in folded)
    return dict(
        period_est=ls["best_period"],
        period_err=err,
        peak_power=ls["peak_power"],
        fap=ls["false_alarm_prob"],
        detected=ls["detected"],
        noise_power=ls_noise["peak_power"],
        noise_fap=ls_noise["false_alarm_prob"],
        fold_amplitude=fold_amp,
        ok=(
            err < 0.005
            and ls["detected"]
            and ls_noise["false_alarm_prob"] > 0.05
            and fold_amp > 0.8
        ),
    )

__link__("analysis.lomb_scargle", [('annotations', 'annotations'), ('math', 'math'), ('Sequence', 'Sequence'), ('_tau_offset', '_tau_offset'), ('lomb_scargle_at', 'lomb_scargle_at'), ('frequency_grid', 'frequency_grid'), ('lomb_scargle', 'lomb_scargle'), ('phase_fold', 'phase_fold'), ('alias_report', 'alias_report'), ('self_check', 'self_check_lomb_scargle')])
# ════════════════════════════════════════════════════════════════════════════

# БЛОК: analysis.mcmc.py  
# ════════════════════════════════════════════════════════════════════════════
__frame__()
"""
TRIVORTEX MASTER — байесовский вывод: MCMC Метрополиса-Гастингса.

Полный стек анализа данных наблюдений (без emcee):

  * MetropolisSampler — случайное блуждание с гауссовым предложением,
    адаптивным шагом (роббинс-монро в фазе burn-in), лог-априорные
    распределения (flat / gaussian / jeffreys);
  * Multi-chain: несколько цепей, диагностика Гельмана-Рубина R̂
    (сходимость при R̂ < 1.1), автокорреляционное время τ (integrated
    autocorrelation time по Солтасу/Гудману);
  * Постераторная статистика: перцентили, среднее/дисперсия, HPD-
    интервалы (highest posterior density, плотнейший 90%);
  * Модель: линейная регрессия + кеплеровская RV-модель (для
    экзопланетных данных: v(t) = K·cos(ν+ω) + γ).

Самопроверка: восстановление наклона/интерсепция зашумлённой прямой
(истина в 90%-HPD), R̂ < 1.05.
"""


import math
import random
from dataclasses import dataclass
from typing import Callable, Sequence

Vector = list[float]


# ═══════════════════════════════════════════════════════════════════════════
# Априорные распределения
# ═══════════════════════════════════════════════════════════════════════════
def flat_prior(theta: Vector, bounds: list[tuple[float, float]]) -> float:
    """Uniform prior: log p = 0 within bounds, −inf outside."""
    for v, (lo, hi) in zip(theta, bounds):
        if not (lo <= v <= hi):
            return float("-inf")
    return 0.0


def gaussian_prior(theta: Vector, means: Vector, sigmas: Vector) -> float:
    """Gaussian prior: Σ log N(μ, σ)."""
    lp = 0.0
    for v, m, s in zip(theta, means, sigmas):
        lp += -0.5 * ((v - m) / s) ** 2 - math.log(s * math.sqrt(2 * math.pi))
    return lp


# ═══════════════════════════════════════════════════════════════════════════
# Правдоподобия
# ═══════════════════════════════════════════════════════════════════════════
def gaussian_loglike(
    model: Callable[[Vector], Vector], data: Vector, sigma: Vector, theta: Vector
) -> float:
    """Gaussian errors log-likelihood: −½Σ((d−m)/σ)²."""
    pred = model(theta)
    ll = 0.0
    for d, p, s in zip(data, pred, sigma):
        ll += -0.5 * ((d - p) / s) ** 2 - math.log(s * math.sqrt(2 * math.pi))
    return ll


# ═══════════════════════════════════════════════════════════════════════════
# Сэмплер Метрополиса-Гастингса
# ═══════════════════════════════════════════════════════════════════════════
@dataclass
class ChainResult:
    """Handle ChainResult."""
    samples: list[Vector]  # после burn-in
    acceptance: float
    log_posterior: list[float]
    n_burn: int


class MetropolisSampler:
    """Adaptive Metropolis-Hastings.

    Proposal step scales to target acceptance ~0.3
    (Robbins-Monro: step *= exp(γ·(acc − 0.3)) in burn-in).
    """

    def __init__(
        self,
        log_posterior: Callable[[Vector], float],
        theta0: Vector,
        step_sizes: Vector,
        seed: int = 42,
        adapt: bool = True,
    ):
        """Do MetropolisSampler.  init for log_posterior, theta0, step_sizes, seed and return the result."""
        self.log_posterior = log_posterior
        self.theta = list(theta0)
        self.step = list(step_sizes)
        self.rng = random.Random(seed)
        self.adapt = adapt
        self.n_accept = 0
        self.n_total = 0

    def _propose(self) -> Vector:
        """Handle MetropolisSampler. propose."""
        return [t + self.rng.gauss(0.0, s) for t, s in zip(self.theta, self.step)]

    def run(self, n_samples: int, burn_in: int = 500) -> ChainResult:
        """Progress bar in frame: ICE fill on dark track."""
        lp = self.log_posterior(self.theta)
        if lp == float("-inf"):
            raise ValueError("стартовая точка имеет нулевой априор")
        samples: list[Vector] = []
        lps: list[float] = []
        n_accept = 0
        for i in range(n_samples + burn_in):
            proposal = self._propose()
            lp_new = self.log_posterior(proposal)
            # лог-отношение
            if lp_new == float("-inf"):
                accept = False
            else:
                log_alpha = lp_new - lp
                accept = math.log(max(self.rng.random(), 1e-300)) < log_alpha
            if accept:
                self.theta = proposal
                lp = lp_new
                n_accept += 1
            # адаптация в burn-in
            if self.adapt and i < burn_in:
                rate = 0.3
                gamma = 0.05
                acc_rate = n_accept / max(i + 1, 1)
                for k in range(len(self.step)):
                    self.step[k] *= math.exp(gamma * (1.0 if acc_rate > rate else -1.0))
                    self.step[k] = max(min(self.step[k], 1e3), 1e-9)
            if i >= burn_in:
                samples.append(list(self.theta))
                lps.append(lp)
        self.n_accept += n_accept
        self.n_total += n_samples + burn_in
        return ChainResult(
            samples=samples,
            acceptance=n_accept / (n_samples + burn_in),
            log_posterior=lps,
            n_burn=burn_in,
        )


# ═══════════════════════════════════════════════════════════════════════════
# Диагностика
# ═══════════════════════════════════════════════════════════════════════════
def gelman_rubin(chains: Sequence[Sequence[Vector]]) -> list[float]:
    """R̂ per parameter (between/within-chain variance).

    chains: list of chain results (samples after burn-in).
    R̂ = sqrt( ((n−1)/n·W + B/n) / W ).
    """
    m = len(chains)
    if m < 2:
        return [float("nan")] * len(chains[0][0])
    n = min(len(c) for c in chains)
    k = len(chains[0][0])
    rhat = []
    for p in range(k):
        means = [sum(s[p] for s in chain) / len(chain) for chain in chains]
        grand = sum(means) / m
        B = n / (m - 1) * sum((mu - grand) ** 2 for mu in means)
        W = (
            sum(
                sum((s[p] - mu) ** 2 for s in chain) / (len(chain) - 1)
                for chain, mu in zip(chains, means)
            )
            / m
        )
        var_hat = (n - 1) / n * W + B / n
        rhat.append(math.sqrt(var_hat / max(W, 1e-300)))
    return rhat


def autocorrelation_time(series: Sequence[float], max_lag: int = 50) -> float:
    """Integrated autocorrelation time (window-method estimate)."""
    n = len(series)
    if n < 10:
        return float("nan")
    mean = sum(series) / n
    var = sum((v - mean) ** 2 for v in series) / n
    if var <= 0:
        return 1.0
    tau = 1.0
    for lag in range(1, min(max_lag, n // 4)):
        cov = sum((series[i] - mean) * (series[i + lag] - mean) for i in range(n - lag)) / (n - lag)
        rho = cov / var
        if rho <= 0:
            break
        tau += 2.0 * rho
    return tau


def posterior_summary(samples: Sequence[Vector], credible: float = 0.9) -> list[dict]:
    """Percentiles + mean/σ + HPD interval per parameter."""
    k = len(samples[0])
    out = []
    for p in range(k):
        vals = sorted(s[p] for s in samples)
        n = len(vals)
        mean = sum(vals) / n
        std = math.sqrt(sum((v - mean) ** 2 for v in vals) / max(n - 1, 1))
        lo_idx = int((1 - credible) / 2 * n)
        hi_idx = int((1 + credible) / 2 * n)
        # HPD: скользящее окно сcredible-долей, минимум ширины
        window = max(int(credible * n), 1)
        best_lo, best_hi = 0, window - 1
        best_width = vals[window - 1] - vals[0]
        for start in range(0, n - window):
            width = vals[start + window - 1] - vals[start]
            if width < best_width:
                best_width = width
                best_lo, best_hi = start, start + window - 1
        out.append(
            dict(
                mean=mean,
                std=std,
                median=vals[n // 2],
                ci_lo=vals[lo_idx],
                ci_hi=vals[hi_idx - 1],
                hpd_lo=vals[best_lo],
                hpd_hi=vals[best_hi],
            )
        )
    return out


# ═══════════════════════════════════════════════════════════════════════════
# Прикладные модели
# ═══════════════════════════════════════════════════════════════════════════
def linear_model(theta: Vector, x: Sequence[float]) -> Vector:
    """y = a + b·x."""
    a, b = theta[0], theta[1]
    return [a + b * xi for xi in x]


def kepler_rv_model(theta: Vector, t: Sequence[float]) -> Vector:
    """RV curve: v = K·cos(ν(t)+ω) + γ, ν from Kepler's equation.

    theta = [K, P, e, omega, gamma].
    """
    from lab.kepler import kepler_E, true_anomaly

    K, P, e, omega, gamma = theta
    out = []
    for ti in t:
        M = 2.0 * math.pi * (ti / P % 1.0)
        E = kepler_E(M, e)
        nu = true_anomaly(E, e)
        out.append(K * math.cos(nu + omega) + gamma)
    return out


# ═══════════════════════════════════════════════════════════════════════════
# Самопроверка
# ═══════════════════════════════════════════════════════════════════════════
def self_check_mcmc() -> dict:
    """Recover y = 2 + 0.5x with noise; truth in 90% HPD."""
    rng = random.Random(3)
    x = [i / 10.0 for i in range(30)]
    a_true, b_true = 2.0, 0.5
    sigma = 0.2
    data = [a_true + b_true * xi + rng.gauss(0, sigma) for xi in x]

    def model(theta):
        return linear_model(theta, x)

    def log_post(theta):
        lp = flat_prior(theta, [(-10, 10), (-10, 10)])
        if lp == float("-inf"):
            return lp
        return lp + gaussian_loglike(model, data, [sigma] * len(x), theta)

    chains = []
    for seed in range(4):
        s = MetropolisSampler(log_post, [1.0, 1.0], [0.12, 0.02], seed=seed)
        chains.append(s.run(4000, burn_in=800).samples)
    rhat = gelman_rubin(chains)
    pooled = [s for c in chains for s in c]
    summ = posterior_summary(pooled, 0.9)
    # МНК-эталон на той же реализации шума: MCMC обязан согласоваться
    # с аналитической оценкой (смещение b относительно истины — свойство
    # конкретной реализации шума, а не сэмплера)
    n_pts = len(x)
    mx = sum(x) / n_pts
    my = sum(data) / n_pts
    sxy = sum((x[i] - mx) * (data[i] - my) for i in range(n_pts))
    sxx = sum((xi - mx) ** 2 for xi in x)
    b_ols = sxy / sxx
    a_ols = my - b_ols * mx
    se_b = sigma / math.sqrt(sxx)
    a_in = summ[0]["hpd_lo"] <= a_ols <= summ[0]["hpd_hi"]
    b_in = summ[1]["hpd_lo"] <= b_ols + 1.645 * se_b and b_ols - 1.645 * se_b <= summ[1]["hpd_hi"]
    b_close = abs(summ[1]["mean"] - b_ols) < 2.0 * se_b
    tau_a = autocorrelation_time([s[0] for s in pooled[:500]])
    return dict(
        a_mean=summ[0]["mean"],
        a_hpd=(summ[0]["hpd_lo"], summ[0]["hpd_hi"]),
        b_mean=summ[1]["mean"],
        b_hpd=(summ[1]["hpd_lo"], summ[1]["hpd_hi"]),
        a_ols=a_ols,
        b_ols=b_ols,
        se_b=se_b,
        rhat=rhat,
        a_in_hpd=a_in,
        b_covers_ols=b_in,
        b_close=b_close,
        tau_a=tau_a,
        n_effective=len(pooled) / max(tau_a, 1.0),
        ok=a_in and b_in and b_close and all(r < 1.1 for r in rhat),
        note="критерий: согласие с МНК-интервалом (аналитика), не с "
        "истиной: смещение оценки — свойство реализации шума",
    )

__link__("analysis.mcmc", [('annotations', 'annotations'), ('math', 'math'), ('random', 'random'), ('dataclass', 'dataclass'), ('field', 'field'), ('Callable', 'Callable'), ('Sequence', 'Sequence'), ('Vector', 'Vector'), ('flat_prior', 'flat_prior'), ('gaussian_prior', 'gaussian_prior'), ('gaussian_loglike', 'gaussian_loglike'), ('ChainResult', 'ChainResult'), ('MetropolisSampler', 'MetropolisSampler'), ('gelman_rubin', 'gelman_rubin'), ('autocorrelation_time', 'autocorrelation_time'), ('posterior_summary', 'posterior_summary'), ('linear_model', 'linear_model'), ('kepler_rv_model', 'kepler_rv_model'), ('self_check', 'self_check_mcmc')])
