# БЛОК: analysis.orbital_elements_fit.py  
# ════════════════════════════════════════════════════════════════════════════
__frame__()
"""
TRIVORTEX MASTER — определение орбиты по наблюдениям (IOD).

Метод на чистом Python:

  * fit_elements_lm: современный подход — 6 элементов как параметры,
    генерация предсказанных RA/Dec на эпохи наблюдений, минимизация
    Лебенбергом-Марквардтом (analysis.fitting) по угловым остаткам.

Самопроверка: синтетические наблюдения известной эллиптической орбиты
(3 точки с шумом 0.01°) — восстановленные a, e в пределах 5%.
"""


import math
from typing import Sequence

from analysis.fitting import LevenbergMarquardt

AU_KM = 1.495978707e8
MU_SUN_KM = 1.32712440018e11  # км³/с²


# ═══════════════════════════════════════════════════════════════════════════
# Кеплеровы элементы → вектор состояния (гелиоцентрический, эклиптика)
# ═══════════════════════════════════════════════════════════════════════════
def elements_to_state_orbital_elements_fit(
    a_au: float,
    e: float,
    i_deg: float,
    om_deg: float,
    w_deg: float,
    M_deg: float,
    mu: float = MU_SUN_KM,
) -> tuple[list, list]:
    """Elements (AU) → (r, v) in km, km/s (perifocal frame →
    rotations i, Ω, ω)."""
    M = math.radians(M_deg)
    # уравнение Кеплера
    E = M
    for _ in range(60):
        dE = (E - e * math.sin(E) - M) / (1 - e * math.cos(E))
        E -= dE
        if abs(dE) < 1e-12:
            break
    xv = a_au * (math.cos(E) - e)
    yv = a_au * math.sqrt(1 - e * e) * math.sin(E)
    # повороты: ω → i → Ω
    w = math.radians(w_deg)
    i_ang = math.radians(i_deg)
    om = math.radians(om_deg)
    x_orb = xv * math.cos(w) - yv * math.sin(w)
    y_orb = xv * math.sin(w) + yv * math.cos(w)
    x_ecl = x_orb
    y_ecl = y_orb * math.cos(i_ang)
    z_ecl = y_orb * math.sin(i_ang)
    x_final = x_ecl * math.cos(om) - y_ecl * math.sin(om)
    y_final = x_ecl * math.sin(om) + y_ecl * math.cos(om)
    r_km = [x_final * AU_KM, y_final * AU_KM, z_ecl * AU_KM]
    # скорость (численно: производная положения по M × dM/dt = n)
    n_rad = math.sqrt(mu / (a_au * AU_KM) ** 3)  # рад/с
    dxdE = -a_au * math.sin(E)
    dydE = a_au * math.sqrt(1 - e * e) * math.cos(E)
    x_orb2 = dxdE * math.cos(w) - dydE * math.sin(w)
    y_orb2 = dxdE * math.sin(w) + dydE * math.cos(w)
    x_ecl2 = x_orb2
    y_ecl2 = y_orb2 * math.cos(i_ang)
    z_ecl2 = y_orb2 * math.sin(i_ang)
    x_fin2 = x_ecl2 * math.cos(om) - y_ecl2 * math.sin(om)
    y_fin2 = x_ecl2 * math.sin(om) + y_ecl2 * math.cos(om)
    v_km = [x_fin2 * AU_KM * n_rad, y_fin2 * AU_KM * n_rad, z_ecl2 * AU_KM * n_rad]
    return r_km, v_km


def propagate_state(r: list, v: list, dt_days: float, mu: float = MU_SUN_KM) -> list:
    """Numerical state propagation (RK4, step 0.5 days)."""

    def deriv(_s, _t):
        x, y, z, vx, vy, vz = _s
        r3 = (x * x + y * y + z * z) ** 1.5
        return [vx, vy, vz, -mu * x / r3, -mu * y / r3, -mu * z / r3]

    dt = 0.5 * 86400.0
    s = [r[0], r[1], r[2], v[0], v[1], v[2]]
    n_steps = max(int(round(dt_days * 86400.0 / dt)), 1)
    for _ in range(n_steps):
        k1 = deriv(s, 0)
        s2 = [s[i] + 0.5 * dt * k1[i] for i in range(6)]
        k2 = deriv(s2, dt / 2)
        s3 = [s[i] + 0.5 * dt * k2[i] for i in range(6)]
        k3 = deriv(s3, dt / 2)
        s4 = [s[i] + dt * k3[i] for i in range(6)]
        k4 = deriv(s4, dt)
        s = [s[i] + dt / 6 * (k1[i] + 2 * k2[i] + 2 * k3[i] + k4[i]) for i in range(6)]
    return s


def geocentric_radec(r_helio_km: list, r_earth_km: list) -> tuple[float, float]:
    """Geocentric RA/Dec (degrees) of object. Earth is heliocentric."""
    dx = [r_helio_km[i] - r_earth_km[i] for i in range(3)]
    d = math.sqrt(sum(c * c for c in dx))
    ra = math.degrees(math.atan2(dx[1], dx[0])) % 360.0
    dec = math.degrees(math.asin(max(-1.0, min(1.0, dx[2] / d))))
    return ra, dec


def earth_position_circular(t_days: float) -> list:
    """Circular Earth model (1 AU, 365.256 days) in km — for demo."""
    ang = 2 * math.pi * t_days / 365.256
    a_km = AU_KM
    return [a_km * math.cos(ang), a_km * math.sin(ang), 0.0]


# ═══════════════════════════════════════════════════════════════════════════
# IOD подгонкой элементов (Лебенберг-Марквардт по RA/Dec)
# ═══════════════════════════════════════════════════════════════════════════
def fit_elements_lm(
    t_obs_days: Sequence[float],
    ra_obs: Sequence[float],
    dec_obs: Sequence[float],
    ra_err_deg: float = 0.01,
    guess: Sequence[float] | None = None,
) -> dict:
    """Determine elements from three+ observations.

    Parameters: [a, e, i, Ω, ω, M0]; predict RA/Dec via
    Keplerian ephemeris + circular Earth (demo model).
    """
    if guess is None:
        guess = [1.8, 0.25, 12.0, 80.0, 200.0, 100.0]

    def model(theta, tt):
        a, e, i_ang, om, w, M0 = theta
        out = []
        for ti in tt:
            M = M0 + 360.0 * math.sqrt(1.0 / a**3) * ti / 365.256
            r_h, _v = elements_to_state_orbital_elements_fit(a, e, i_ang, om, w, M % 360.0)
            ra, dec = geocentric_radec(r_h, earth_position_circular(ti))
            out.extend([ra, dec])
        return out

    y_data = []
    for ra, dec in zip(ra_obs, dec_obs):
        y_data.extend([ra, dec])
    n_pts = len(t_obs_days)
    sigma = [ra_err_deg] * (2 * n_pts)
    lm = LevenbergMarquardt(model, list(t_obs_days), y_data, sigma, h_step=1e-7)
    fit = lm.fit(list(guess), max_iter=80)
    return dict(
        elements=list(fit["theta"]),
        errors=(fit["errors"] or [None] * 6),
        chi2=fit["chi2"],
        dof=fit["dof"],
        reduced_chi2=fit["reduced_chi2"],
        n_iter=fit["n_iter"],
        converged=fit["converged"],
        method="LM по угловым остаткам (круговая Земля, без св. времени)",
    )


# ═══════════════════════════════════════════════════════════════════════════
# Метод Гиббса (Гаусс, классика) — вектор r₂ из трёх векторов
# ═══════════════════════════════════════════════════════════════════════════
# ═══════════════════════════════════════════════════════════════════════════
# Самопроверка
# ═══════════════════════════════════════════════════════════════════════════
def self_check_orbital_elements_fit() -> dict:
    """Synthetic object a=1.8, e=0.25: IOD recovers a, e."""
    import random

    rng = random.Random(31)
    a_true, e_true = 1.8, 0.25
    i_t, om_t, w_t, M0_t = 12.0, 80.0, 200.0, 100.0
    # 5 эпох = 10 наблюдений (6 параметров → dof=4; при 3 эпохах
    # система недоопределена и LM не сходится)
    t_obs = [0.0, 9.0, 18.0, 27.0, 36.0]
    ra_obs, dec_obs = [], []
    for ti in t_obs:
        M = M0_t + 360.0 * math.sqrt(1 / a_true**3) * ti / 365.256
        r_h, _ = elements_to_state_orbital_elements_fit(a_true, e_true, i_t, om_t, w_t, M % 360)
        ra, dec = geocentric_radec(r_h, earth_position_circular(ti))
        ra_obs.append(ra + rng.gauss(0, 0.01))
        dec_obs.append(dec + rng.gauss(0, 0.01))
    fit = fit_elements_lm(
        t_obs, ra_obs, dec_obs, ra_err_deg=0.01, guess=[1.5, 0.2, 10.0, 70.0, 190.0, 90.0]
    )
    a_fit, e_fit = fit["elements"][0], fit["elements"][1]
    a_ok = abs(a_fit - a_true) / a_true < 0.05
    e_ok = abs(e_fit - e_true) < 0.05
    # остатки предсказаний обязаны быть на уровне шума (χ²_red ≈ 1)
    resid_ok = fit["reduced_chi2"] < 4.0
    return dict(
        a_fit=round(a_fit, 4),
        e_fit=round(e_fit, 4),
        a_true=a_true,
        e_true=e_true,
        reduced_chi2=fit["reduced_chi2"],
        n_iter=fit["n_iter"],
        a_ok=a_ok,
        e_ok=e_ok,
        resid_ok=resid_ok,
        all_ok=a_ok and e_ok and resid_ok,
        note="IOD: LM по 6 элементам, 5 эпох (dof=4), круговая Земля",
    )

__link__("analysis.orbital_elements_fit", [('annotations', 'annotations'), ('math', 'math'), ('Sequence', 'Sequence'), ('LevenbergMarquardt', 'LevenbergMarquardt'), ('AU_KM', 'AU_KM'), ('MU_SUN_KM', 'MU_SUN_KM'), ('elements_to_state', 'elements_to_state_orbital_elements_fit'), ('propagate_state', 'propagate_state'), ('geocentric_radec', 'geocentric_radec'), ('earth_position_circular', 'earth_position_circular'), ('fit_elements_lm', 'fit_elements_lm'), ('self_check', 'self_check_orbital_elements_fit')])
# ════════════════════════════════════════════════════════════════════════════

# БЛОК: analysis.periodogram.py  
# ════════════════════════════════════════════════════════════════════════════
__frame__()
"""
TRIVORTEX MASTER — BLS: поиск транзитов в кривых блеска.

Box Least Squares (Kovács, Zucker & Mazeh 2002, A&A 391, 369) на
чистом Python:

  * bls(t, y, periods, n_bins): фазовая свёртка, перебор фаз входа,
    box-модель (глубина δ, длительность q), критерий SR (signal
    residue) по формуле оригинала;
  * sde: Signal Detection Efficiency = (SR_max − μ_SR)/σ_SR
    (анализ двухпроходного фона — Kovács 2002 §3.4);
  * best_box: период, эпоха, глубина, длительность, SNR.

Самопроверка: синтетическая кривая (P = 3.5 сут, глубина 1%, шум
200 ppm, 300 точек с пропусками) — период восстановлен, SDE > 5.
"""


import math
from typing import Sequence


def _phase_bin(
    t: Sequence[float], y: Sequence[float], period: float, t0: float, n_bins: int
) -> list[float]:
    """Mean magnitude per phase bins (phase from t0)."""
    sums = [0.0] * n_bins
    counts = [0] * n_bins
    for ti, yi in zip(t, y):
        ph = ((ti - t0) / period) % 1.0
        idx = min(int(ph * n_bins), n_bins - 1)
        sums[idx] += yi
        counts[idx] += 1
    return [s / c if c else float("nan") for s, c in zip(sums, counts)]


def bls_at_period(
    t: Sequence[float],
    y: Sequence[float],
    period: float,
    n_bins: int = 200,
    duration_fracs: Sequence[float] = (0.015, 0.03, 0.05, 0.075),
) -> dict:
    """BLS statistics SR on one period: phase entry × duration grid search.

    Criterion: depth SNR: SR = δ·√(N·r_t)/σ (standard transit pipeline
    criterion; signal residue variant from Kovács 2002).
    Duration grid search is mandatory, otherwise the peak shifts.
    """
    n = len(t)
    mean_y = sum(y) / n
    sigma = math.sqrt(sum((v - mean_y) ** 2 for v in y) / n)
    best = dict(sr=-1.0, depth=0.0, epoch=0.0, duration=0.0)
    for dur_frac in duration_fracs:
        n_dur = max(int(round(dur_frac * n_bins)), 2)
        for k in range(n_bins):
            in_bins = {(k + j) % n_bins for j in range(n_dur)}
            in_sum = 0.0
            in_count = 0
            for ti, yi in zip(t, y):
                b = min(int(((ti / period) % 1.0) * n_bins), n_bins - 1)
                if b in in_bins:
                    in_sum += yi
                    in_count += 1
            out_count = n - in_count
            if in_count < 2 or out_count == 0:
                continue
            mean_in = in_sum / in_count
            mean_out = (sum(y) - in_sum) / out_count
            depth = mean_out - mean_in
            if depth <= 0:
                continue
            r_t = in_count / n
            sr = depth * math.sqrt(n * r_t) / sigma
            epoch = (k / n_bins) * period
            if sr > best["sr"]:
                best = dict(sr=sr, depth=depth, epoch=epoch, duration=dur_frac * period)
    return best


def bls(
    t: Sequence[float], y: Sequence[float], periods: Sequence[float], n_bins: int = 200
) -> dict:
    """Full BLS periodogram: SR on period grid + SDE."""
    results = []
    for p in periods:
        b = bls_at_period(t, y, p, n_bins)
        results.append((p, b["sr"], b))
    srs = [s for _p, s, _b in results]
    mean_sr = sum(srs) / len(srs)
    std_sr = math.sqrt(sum((s - mean_sr) ** 2 for s in srs) / max(len(srs) - 1, 1))
    best_p, best_sr, best_box = max(results, key=lambda r: r[1])
    sde = (best_sr - mean_sr) / max(std_sr, 1e-12)
    # SNR по глубине: δ/σ_δ, σ_δ ≈ σ/√(число точек в транзите)
    n = len(t)
    noise = math.sqrt(sum((v - sum(y) / n) ** 2 for v in y) / n)
    n_in = max(int(n * 0.02), 1)
    snr = best_box["depth"] / (noise / math.sqrt(n_in))
    return dict(
        period=best_p,
        sr=best_sr,
        sde=sde,
        depth=best_box["depth"],
        epoch=best_box["epoch"],
        duration=best_box["duration"],
        snr=snr,
        mean_sr=mean_sr,
        std_sr=std_sr,
        detected=(sde > 5.0 and snr > 4.0),
    )


def period_grid(
    t_min: float, t_span: float, p_min: float, p_max: float, n: int = 2000
) -> list[float]:
    """Log period grid from p_min to p_max (n points)."""
    return [p_min * (p_max / p_min) ** (i / (n - 1)) for i in range(n)]


def self_check_periodogram() -> dict:
    """Synthetic transit: period 3.5 d, depth 1%, SDE > 5."""
    import random

    rng = random.Random(17)
    period_true, depth_true, duration_true = 3.5, 0.01, 0.12
    t = sorted(rng.uniform(0, 60) for _ in range(300))
    y = []
    for ti in t:
        ph = (ti % period_true) / period_true
        v = 0.0
        if ph < duration_true / period_true:
            v -= depth_true  # транзит
        y.append(v + rng.gauss(0, 0.0002))  # 200 ppm
    grid = period_grid(0, 60, 1.0, 15.0, n=1500)
    res = bls(t, y, grid, n_bins=120)
    p_err = abs(res["period"] - period_true) / period_true
    return dict(
        period_est=res["period"],
        period_err=p_err,
        depth_est=res["depth"],
        sde=res["sde"],
        snr=res["snr"],
        detected=res["detected"],
        ok=(p_err < 0.02 and res["detected"] and res["sde"] > 5.0),
        note="Kovács, Zucker & Mazeh 2002 (BLS); сетка 1–15 сут, 120 бинов",
    )

__link__("analysis.periodogram", [('annotations', 'annotations'), ('math', 'math'), ('Sequence', 'Sequence'), ('_phase_bin', '_phase_bin'), ('bls_at_period', 'bls_at_period'), ('bls', 'bls'), ('period_grid', 'period_grid'), ('self_check', 'self_check_periodogram')])
# ════════════════════════════════════════════════════════════════════════════

# БЛОК: analysis.pipeline.py  
# ════════════════════════════════════════════════════════════════════════════
__frame__()
"""
TRIVORTEX MASTER — конвейер анализа данных (пайплайн).

Декларативный конвейер: шаги с зависимостями, кэширование по хэшу
входов, изоляция сбоев и отчёт о происхождении данных (provenance):

  * PipelineStep: имя, функция, входы (имена других шагов), тег
    версии функции (для инвалидации кэша);
  * Pipeline: ориентированный ациклический граф шагов; топологическая
    сортировка ( Кана 1962 ), прогон с мемоизацией результатов;
  * сбой шага не валит конвейер: зависимые шаги помечаются skipped,
    независимые выполняются;
  * provenance: для каждого результата — дерево происхождения
    (какие шаги и с какими версиями участвовали);
  * validate: проверка контрактов (тип результата, схема dict).

Самопроверка: DAG из 5 шагов выполняется в правильном порядке;
кэш даёт второй прогон без вычислений; сбой изолируется; цикл
обнаруживается.
"""


import hashlib
import json
import time
from dataclasses import dataclass, field
from typing import Any, Callable


# ═══════════════════════════════════════════════════════════════════════════
# Шаг конвейера
# ═══════════════════════════════════════════════════════════════════════════
@dataclass
class PipelineStep:
    """Single step: function of input results dictionary."""

    name: str
    func: Callable[[dict[str, Any]], Any]
    inputs: tuple[str, ...] = ()
    version: str = "1"  # изменение версии инвалидирует кэш
    validator: Callable[[Any], list[str]] | None = None

    def signature(self) -> str:
        """Perspective projection (OpenGL-style, z in [-1,1])."""
        payload = json.dumps(
            dict(name=self.name, v=self.version, inputs=list(self.inputs)), sort_keys=True
        )
        return hashlib.sha256(payload.encode()).hexdigest()[:16]


@dataclass
class StepResult:
    """Step result: value or error + origin."""

    step: str
    ok: bool
    value: Any = None
    error: str = ""
    duration_s: float = 0.0
    from_cache: bool = False
    provenance: list[str] = field(default_factory=list)


# ═══════════════════════════════════════════════════════════════════════════
# Конвейер
# ═══════════════════════════════════════════════════════════════════════════
class Pipeline:
    """DAG of steps with caching and failure isolation."""

    def __init__(self, name: str = "pipeline"):
        """Do Pipeline.  init for name and return the result."""
        self.name = name
        self.steps: dict[str, PipelineStep] = {}
        self.results: dict[str, StepResult] = {}
        self._cache: dict[str, Any] = {}

    def add(self, step: PipelineStep) -> Pipeline:
        """Do Pipeline.add for step and return the result."""
        if step.name in self.steps:
            raise ValueError(f"шаг уже есть: {step.name}")
        self.steps[step.name] = step
        return self

    # ── топология ──
    def topo_order(self) -> list[str]:
        """Vertices and triangles of UV-sphere (poles along y)."""
        indeg = {name: 0 for name in self.steps}
        dependents: dict[str, list[str]] = {name: [] for name in self.steps}
        for name, step in self.steps.items():
            for inp in step.inputs:
                if inp not in self.steps:
                    raise ValueError(f"{name}: вход {inp} не объявлен")
                indeg[name] += 1
                dependents[inp].append(name)
        queue = sorted(n for n, d in indeg.items() if d == 0)
        order = []
        while queue:
            n = queue.pop(0)
            order.append(n)
            for m in dependents[n]:
                indeg[m] -= 1
                if indeg[m] == 0:
                    queue.append(m)
            queue.sort()
        if len(order) != len(self.steps):
            cyclic = sorted(n for n, d in indeg.items() if d > 0)
            raise ValueError(f"цикл в графе шагов: {cyclic}")
        return order

    # ── прогон ──
    def run(self, use_cache: bool = True) -> dict[str, StepResult]:
        """RGB frame with z-buffer."""
        self.results = {}
        for name in self.topo_order():
            step = self.steps[name]
            # входы: значения успешных шагов
            inputs_ok = all(
                self.results.get(i) is not None and self.results[i].ok for i in step.inputs
            )
            if not inputs_ok:
                failed = [
                    i for i in step.inputs if self.results.get(i) is None or not self.results[i].ok
                ]
                self.results[name] = StepResult(
                    step=name, ok=False, error=f"пропущен: входы недоступны ({failed})"
                )
                continue
            key = step.signature()
            if use_cache and key in self._cache:
                self.results[name] = StepResult(
                    step=name,
                    ok=True,
                    value=self._cache[key],
                    from_cache=True,
                    provenance=self._provenance_of(name),
                )
                continue
            args = {i: self.results[i].value for i in step.inputs}
            t0 = time.perf_counter()
            try:
                value = step.func(args)
                errors = []
                if step.validator is not None:
                    errors = step.validator(value) or []
                if errors:
                    self.results[name] = StepResult(
                        step=name, ok=False, error=f"контракт нарушен: {errors}"
                    )
                    continue
                duration = time.perf_counter() - t0
                self.results[name] = StepResult(
                    step=name,
                    ok=True,
                    value=value,
                    duration_s=duration,
                    provenance=self._provenance_of(name),
                )
                self._cache[key] = value
            except Exception as exc:
                self.results[name] = StepResult(
                    step=name, ok=False, error=f"{type(exc).__name__}: {exc}"
                )

        return self.results

    def _provenance_of(self, name: str) -> list[str]:
        """trails: list of trails (list[(x,y,z)]) per body — drawn as lines."""
        step = self.steps[name]
        chain = [f"{name}@{step.version}"]
        for inp in step.inputs:
            res = self.results.get(inp)
            if res is not None:
                chain.extend(res.provenance)
        return sorted(set(chain))

    # ── сводка ──
    def summary(self) -> dict:
        """Handle Pipeline.summary."""
        ok_n = sum(1 for r in self.results.values() if r.ok)
        cached_n = sum(1 for r in self.results.values() if r.from_cache)
        return dict(
            name=self.name,
            steps=len(self.results),
            ok=ok_n,
            failed=len(self.results) - ok_n,
            cached=cached_n,
            total_s=sum(r.duration_s for r in self.results.values()),
            failed_steps=[r.step for r in self.results.values() if not r.ok],
        )


# ═══════════════════════════════════════════════════════════════════════════
# Самопроверка
# ═══════════════════════════════════════════════════════════════════════════
def self_check_pipeline() -> dict:
    """DAG 5 steps: order, cache hit, failure isolation, loop caught,
    contract validator works, provenance is transitive."""
    # ── построение ──
    calls: list[str] = []
    pipe = Pipeline("test")

    def make_raw(_):
        calls.append("raw")
        return list(range(10))

    def clean(args):
        calls.append("clean")
        return [v * 2 for v in args["raw"]]

    def stats(args):
        calls.append("stats")
        data = args["clean"]
        return dict(mean=sum(data) / len(data), n=len(data))

    def report(args):
        calls.append("report")
        return f"mean={args['stats']['mean']:.1f}"

    pipe.add(PipelineStep("raw", make_raw))
    pipe.add(PipelineStep("clean", clean, inputs=("raw",)))
    pipe.add(PipelineStep("stats", stats, inputs=("clean",)))
    pipe.add(
        PipelineStep(
            "report",
            report,
            inputs=("stats",),
            validator=lambda v: [] if isinstance(v, str) and len(v) > 0 else ["не строка/пусто"],
        )
    )
    # порядок
    order = pipe.topo_order()
    order_ok = (
        order.index("raw") < order.index("clean") < order.index("stats") < order.index("report")
    )
    # первый прогон: все вычислены
    res1 = pipe.run(use_cache=True)
    first_ok = all(r.ok for r in res1.values())
    computed_n = len(calls)
    # второй прогон: всё из кэша
    calls.clear()
    res2 = pipe.run(use_cache=True)
    cache_ok = len(calls) == 0 and all(r.from_cache for r in res2.values())
    # сбой изолируется: чистка падает, отчёт скипается, сырьё живёт
    pipe2 = Pipeline("fail")
    pipe2.add(PipelineStep("raw", make_raw))
    pipe2.add(PipelineStep("bad", lambda a: 1 / 0, inputs=("raw",)))
    pipe2.add(PipelineStep("independent", lambda a: 42))
    res3 = pipe2.run(use_cache=False)
    isolation_ok = (
        res3["raw"].ok
        and not res3["bad"].ok
        and res3["independent"].ok
        and "ZeroDivisionError" in res3["bad"].error
    )
    # цикл ловится
    pipe3 = Pipeline("cycle")
    pipe3.add(PipelineStep("a", lambda x: 1, inputs=("b",)))
    pipe3.add(PipelineStep("b", lambda x: 1, inputs=("a",)))
    try:
        pipe3.topo_order()
        cycle_ok = False
    except ValueError as exc:
        cycle_ok = "цикл" in str(exc)
    # provenance транзитивен
    prov = res1["report"].provenance
    prov_ok = any("raw@" in p for p in prov) and any("stats@" in p for p in prov)
    # валидатор отвергает мусор
    pipe4 = Pipeline("contract")
    pipe4.add(PipelineStep("bad_out", lambda a: "", validator=lambda v: ["пусто"]))
    res4 = pipe4.run(use_cache=False)
    contract_ok = not res4["bad_out"].ok and "контракт" in res4["bad_out"].error
    summ = pipe.summary()
    return dict(
        order_ok=order_ok,
        first_run_ok=first_ok,
        computed_first=computed_n,
        cache_ok=cache_ok,
        isolation_ok=isolation_ok,
        cycle_detected=cycle_ok,
        provenance_ok=prov_ok,
        contract_ok=contract_ok,
        summary=dict(ok=summ["ok"], total=summ["steps"]),
        all_ok=order_ok
        and first_ok
        and cache_ok
        and isolation_ok
        and cycle_ok
        and prov_ok
        and contract_ok,
        note="топология Кана 1962; кэш по sha256(имя,версия,входы); "
        "сбой шага изолируется, зависимые скипаются",
    )

__link__("analysis.pipeline", [('annotations', 'annotations'), ('hashlib', 'hashlib'), ('json', 'json'), ('time', 'time'), ('dataclass', 'dataclass'), ('field', 'field'), ('Any', 'Any'), ('Callable', 'Callable'), ('PipelineStep', 'PipelineStep'), ('StepResult', 'StepResult'), ('Pipeline', 'Pipeline'), ('self_check', 'self_check_pipeline')])
