import importlib.util
import json
import os
import subprocess
import sys
from dataclasses import dataclass, field

# Эталонные значения Теоремы 3.1 при C_Ch = 1, T = 2π.
# Формулы — из кода репозитория (verification/trivortex/python/verify.py,
