"""
TRIVORTEX MASTER — структурные и интеграционные тесты S1–S12.

S1  структура сцены          S7  энергия ньютоновского RK4
S2  сериализация             S8  сравнение движков (native vs REBOUND)
S3  направления зависимостей S9  траектории (Теорема 3.1, 2π/3)
S4  реестр режимов           S10 рендер-контракты
S5  интегралы V3 (равные Γ)  S11 отчёты (7 форматов)
S6  интегралы V4 (Γ=1,2,3)   S12 лимит N=8 (порог Хавелока)

Запуск: из меню («Анализ») или python3 trivortex_master.py --selftest
"""


import importlib
import math
import os
from importlib.util import find_spec
from typing import Any

from core.config import MasterConfig, UnphysicalConfiguration, from_profile
from lab.body import Body
from lab.physics import run_simulation
from lab.scene import Scene
from lab.trajectory import get_planner

ROOT = _PKG_ROOT


class TestResult:
    """One structural test's outcome: id, title, details, metrics."""
    def __init__(self, test_id: str, name: str):
        """Do TestResult.  init for test_id, name and return the result."""
        self.id = test_id
        self.name = name
        # оптимистичный старт: тест считается прошедшим, пока какой-нибудь
        # check()/fail() его не провалит; успех отдельного чека НЕ воскрешает
        # проваленный ранее чек (до v2.0.1 поздний успех затирал ранний ✗)
        self.passed = True
        self.details: list[str] = []
        self.metrics: dict[str, Any] = {}

    def ok(self, msg: str = "") -> TestResult:
        """Return True when all checks passed."""
        self.passed = True
        if msg:
            self.details.append(msg)
        return self

    def fail(self, msg: str) -> TestResult:
        """Do TestResult.fail for msg and return the result."""
        self.passed = False
        self.details.append(msg)
        return self

    def check(self, cond: bool, ok_msg: str, fail_msg: str) -> bool:
        """Append a detail line; a failed check fails the test."""
        if cond:
            self.details.append(ok_msg)
        else:
            self.details.append("✗ " + fail_msg)
            self.passed = False
        return cond

    def to_dict(self) -> dict[str, Any]:
        """Handle TestResult.to dict."""
        return dict(
            id=self.id,
            name=self.name,
            passed=self.passed,
            details=self.details,
            metrics=self.metrics,
        )


# ═══════════════════════════════════════════════════════════════════════════
# S1 — структура сцены
# ═══════════════════════════════════════════════════════════════════════════
def test_s1() -> TestResult:
    """Handle test s1."""
    r = TestResult("S1", "структура сцены")
    from lab.presets import load_presets, build_preset

    cfg = from_profile("quick", n_steps=5)
    presets = load_presets()
    r.metrics["presets"] = len(presets)
    ok_count = 0
    skipped_unphysical = 0
    for p in presets:
        try:
            if p.get("unphysical"):
                skipped_unphysical += 1
                continue
            sc = build_preset(p["id"], cfg)
            rep = sc.validate()
            if rep.ok:
                ok_count += 1
            else:
                r.details.append(f"пресет {p['id']}: {rep.problems}")
        except Exception as exc:
            r.details.append(f"пресет {p['id']}: {type(exc).__name__}: {exc}")
    suffix = (
        f" (+{skipped_unphysical} unphysical-пресет пропущен по флагу)"
        if skipped_unphysical
        else ""
    )
    r.check(
        ok_count >= 8,
        f"пресетов без проблем: {ok_count}/{len(presets) - skipped_unphysical}{suffix}",
        f"слишком много проблем: {ok_count}/{len(presets) - skipped_unphysical}",
    )
    # тела валидны
    sc = build_preset("inner_solar", cfg)
    r.check(
        all(not b.validate() for b in sc.bodies),
        "все тела Scene.validate чисты",
        "есть невалидные тела",
    )
    return r.ok() if r.passed else r


