def _load_extra():
    """S13–S24 from tests_extra (modules with independent references)."""
    try:
        from analysis.tests_extra import EXTRA_TESTS

        return list(EXTRA_TESTS)
    except ImportError:
        return []


ALL_TESTS = [
    test_s1,
    test_s2,
    test_s3,
    test_s4,
    test_s5,
    test_s6,
    test_s7,
    test_s8,
    test_s9,
    test_s10,
    test_s11,
    test_s12,
    *_load_extra(),
]


def run_all_tests(tests: list[str] | None = None, verbose: bool = True) -> dict[str, Any]:
    """Run selected (or all) tests; returns summary."""
    results = []
    for fn in ALL_TESTS:
        if tests and fn.__name__.replace("test_", "") not in tests:
            continue
        try:
            res = fn()
        except Exception as exc:
            res = TestResult(fn.__name__.replace("test_", "").upper(), fn.__doc__ or "")
            res.fail(f"исключение: {type(exc).__name__}: {exc}")
        results.append(res)
        if verbose:
            mark = "✓" if res.passed else "✗"
            print(f"  [{mark}] {res.id} {res.name}")
            for d in res.details[:3]:
                print(f"        {d}")
    passed = sum(1 for r in results if r.passed)
    summary = dict(
        total=len(results),
        passed=passed,
        failed=len(results) - passed,
        results=[r.to_dict() for r in results],
        all_pass=passed == len(results),
    )
    return summary

