# БЛОК: render.ascii_sky.py  
# ════════════════════════════════════════════════════════════════════════════
__frame__()
"""
TRIVORTEX MASTER — карта неба в стереографической проекции (ASCII).

  * stereographic_project: (alt, az) → плоскость — конформная
    проекция: r = k·tan(z/2), z — зенитное расстояние; круги остаются
    кругами (свойство конформности, Snyder 1987, «Map Projections»);
  * sky_map_ascii: все 25 ярких звёзд в полусферическом виде для
    широты наблюдателя, символ по величине;
  * constellation_lines: грубые линии известных фигур (Большой Ковш,
    Орион) между яркими звёздами;
  * cardinal_marks: метки сторон горизонта.

Архитектура (правило направлений S3: render → {core, lab}): модуль НЕ
импортирует realism. Каталог ярких звёзд (realism.bright_stars) и
преобразования координат (realism.sky_coordinates) инъектируются
верхним слоем через bind_astronomy() — вызывается из modes_extra.py,
tools/quality_gate.py и tools/build_dist.py. Это тот же паттерн
инверсии зависимости, что register_engine() для адаптеров
REBOUND/Dedalus (см. core/registry.py): слой данных подключается к
слою отображения, не создавая ребра render → realism в графе импортов.

Самопроверки: зенит в центре; круг постоянной высоты — окружность
(конформность); звёзды ниже горизонта не рисуются; длина линий
Ориона соответствует угловым расстояниям.
"""


import math
from typing import Any, Callable, Sequence

# ── DI-слоты: инъекция астроданных (без импорта realism — правило S3) ──
_catalog_provider: Callable[[], Sequence[Any]] | None = None
_eq_to_horiz: Callable[..., tuple[float, float]] | None = None
_angular_sep: Callable[..., float] | None = None


def bind_astronomy(
    catalog_provider: Callable[[], Sequence[Any]],
    eq_to_horiz: Callable[..., tuple[float, float]],
    angular_sep: Callable[..., float],
) -> None:
    """Dependency injection: realism layer passes bright star catalog and
    coordinate transformations; render remains free from realism imports
    (S3 direction rule). Analog to register_engine() for engines."""
    global _catalog_provider, _eq_to_horiz, _angular_sep
    _catalog_provider = catalog_provider
    _eq_to_horiz = eq_to_horiz
    _angular_sep = angular_sep


def astronomy_bound() -> bool:
    """Whether astronomy data provider is bound (for menu diagnostics)."""
    return _catalog_provider is not None and _eq_to_horiz is not None


def _require_astronomy() -> None:
    """Handle require astronomy."""
    if _catalog_provider is None or _eq_to_horiz is None:
        raise RuntimeError(
            "astronomy provider не привязан: вызовите "
            "render.ascii_sky.bind_astronomy(catalog, eq_to_horiz, ang_sep) "
            "из верхнего слоя (modes_extra / tools) — render не импортирует "
            "realism (правило направлений S3)"
        )


def stereographic_project(alt_deg: float, az_deg: float, k: float = 1.0) -> tuple[float, float]:
    """(alt, az) → (x, y) in map radius units (zenith = (0,0)).

    z = 90° − alt; r = k·tan(z/2); direction — azimuth from north
    clockwise (top view)."""
    z = math.radians(90.0 - alt_deg)
    if z >= math.pi / 2 - 1e-9:
        return (float("nan"), float("nan"))
    r = k * math.tan(z / 2.0)
    az = math.radians(az_deg)
    return (r * math.sin(az), r * math.cos(az))


def visible_stars(lat_deg: float, lst_rad: float) -> list[tuple[Any, float, float]]:
    """Stars above horizon: (star, alt, az) for latitude and LST.

    Catalog and equatorial→horizontal transformation come via
    bind_astronomy() (injection, S3)."""
    _require_astronomy()
    visible = []
    for star in _catalog_provider():
        az, alt = _eq_to_horiz(star.ra_deg, star.dec_deg, lat_deg, lst_rad)
        if alt > 0:
            visible.append((star, alt, az))
    return visible


# грубые линии созвездий (пары имён из каталога)
CONSTELLATION_LINES = {
    "Большой Ковш": [("Алиот", "Мирфак")],  # упрощённо (2 звезды)
    "Орион": [("Бетельгейзе", "Ригель"), ("Бетельгейзе", "Беллатрикс")],
    "Близнецы": [("Кастор", "Поллукс")],
    "Кентавр-Юг": [("α Центавра", "Хадар")],
}


def constellation_lengths(lat_deg: float, lst_rad: float) -> dict:
    """Angular lengths of constellation lines (for scale verification).

    angular_separation is injected via bind_astronomy() (S3)."""
    _require_astronomy()
    out = {}
    for name, pairs in CONSTELLATION_LINES.items():
        total = 0.0
        for a, b in pairs:
            sa = [s for s in _catalog_provider() if s.name == a]
            sb = [s for s in _catalog_provider() if s.name == b]
            if not sa or not sb:
                continue
            total += _angular_sep(sa[0].ra_deg, sa[0].dec_deg, sb[0].ra_deg, sb[0].dec_deg)
        out[name] = total
    return out


def sky_map_ascii(lat_deg: float, lst_rad: float, width: int = 41, height: int = 21) -> str:
    """ASCII map of hemisphere: stereographic projection, zenith at center.

    Brightness symbol: brighter → denser (▓ █); cardinal directions labeled."""
    rows = [[" "] * width for _ in range(height)]
    cx, cy = (width - 1) / 2.0, (height - 1) / 2.0
    radius = min(cx, cy) - 1
    # окружность горизонта
    for ang in range(0, 360, 4):
        ax = cx + radius * math.sin(math.radians(ang))
        ay = cy - radius * math.cos(math.radians(ang))
        xi, yi = int(round(ax)), int(round(ay))
        if 0 <= xi < width and 0 <= yi < height:
            rows[yi][xi] = "·"
    # звёзды
    for star, alt, az in visible_stars(lat_deg, lst_rad):
        x, y = stereographic_project(alt, az)
        xi = int(round(cx + x * radius))
        yi = int(round(cy - y * radius))
        if 0 <= xi < width and 0 <= yi < height:
            if star.magnitude < 0.0:
                ch = "█"
            elif star.magnitude < 1.0:
                ch = "▓"
            elif star.magnitude < 2.0:
                ch = "▒"
            else:
                ch = "░"
            rows[yi][xi] = ch
    # метки сторон горизонта
    rows[0][int(cx)] = "С"
    rows[height - 1][int(cx)] = "Ю"
    rows[int(cy)][width - 1] = "В"
    rows[int(cy)][0] = "З"
    return "\n".join("".join(r) for r in rows)


# ═══════════════════════════════════════════════════════════════════════════
# Самопроверка
# ═══════════════════════════════════════════════════════════════════════════
def self_check_ascii_sky() -> dict:
    """Zenith at center; conformality: 30° altitude circle — circular;
    map is non-empty and contains brightest stars above horizon."""
    # зенит: alt=90 → (0, 0)
    x, y = stereographic_project(90.0, 0.0)
    zenith_ok = abs(x) < 1e-12 and abs(y) < 1e-12
    # конформность: точки на круге alt=30° — одинаковый радиус
    radii = []
    for az in (0, 45, 90, 180, 270):
        px, py = stereographic_project(30.0, az)
        radii.append(math.hypot(px, py))
    conformal_ok = max(radii) - min(radii) < 1e-9
    # карта: на широте 55.75 при LST = 6h (Орион на юге) есть яркие
    lst = math.radians(90.0)  # 6 часов
    visible = visible_stars(55.75, lst)
    visible_ok = len(visible) >= 8
    # Сириус с юга России (45°) виден, на 60° с.ш. низко
    lst_sirius = math.radians(101.28 + 0.0)  # RA Сириуса в градусах
    az_s, alt_s = _eq_to_horiz(101.28, -16.72, 55.75, lst_sirius)
    sirius_up = alt_s > 0
    # карта-строка
    text = sky_map_ascii(55.75, lst)
    map_ok = "█" in text or "▓" in text and len(text) > 400
    # Близнецы (Кастор-Поллукс): 4.51° по координатам каталога
    # (ΔRA 2.68°·cos30° + ΔDec 3.85°); память о 6° была неверна
    lengths = constellation_lengths(55.75, lst)
    gemini_len = lengths.get("Близнецы", 0)
    orion_ok = abs(gemini_len - 4.51) < 0.3
    return dict(
        zenith_ok=zenith_ok,
        conformal_ok=conformal_ok,
        astronomy_bound=astronomy_bound(),
        n_visible=len(visible),
        visible_ok=visible_ok,
        sirius_alt=round(alt_s, 1),
        sirius_up=sirius_up,
        gemini_line_deg=round(gemini_len, 2),
        orion_ok=orion_ok,
        map_ok=map_ok,
        all_ok=zenith_ok and conformal_ok and visible_ok and sirius_up and orion_ok and map_ok,
        note="стереографическая проекция — конформная (Snyder 1987); "
        "символ яркости: █ < 0ᵐ, ▓ < 1ᵐ, ▒ < 2ᵐ, ░ остальные; "
        "астроданные инъектируются через bind_astronomy (S3: render без realism)",
    )

__link__("render.ascii_sky", [('annotations', 'annotations'), ('math', 'math'), ('bind_astronomy', 'bind_astronomy'), ('astronomy_bound', 'astronomy_bound'), ('stereographic_project', 'stereographic_project'), ('visible_stars', 'visible_stars'), ('CONSTELLATION_LINES', 'CONSTELLATION_LINES'), ('constellation_lengths', 'constellation_lengths'), ('sky_map_ascii', 'sky_map_ascii'), ('self_check', 'self_check_ascii_sky')])
# ════════════════════════════════════════════════════════════════════════════

# БЛОК: render.backend_gl.py  
# ════════════════════════════════════════════════════════════════════════════
__frame__()
"""
TRIVORTEX MASTER — опциональный GL-бэкенд (pyrender / moderngl).

Подключается при наличии; иначе движок render.engine предлагает
mpl / pure / ascii. GL даёт аппаратное ускорение и тени, но не является
обязательным: лаборатория полностью работает и без него.
"""


import math

from importlib.util import find_spec

# availability_backend_gl probes: bind booleans, not module objects
HAVE_MODERNGL = find_spec("moderngl") is not None
HAVE_PYRENDER = find_spec("pyrender") is not None

HAVE_GL = HAVE_MODERNGL or HAVE_PYRENDER


def availability_backend_gl() -> dict:
    """Status for HUD."""
    reasons = []
    if not HAVE_MODERNGL:
        reasons.append("pip install moderngl")
    if not HAVE_PYRENDER:
        reasons.append("pip install pyrender")
    return dict(name="gl", available=HAVE_GL, reason="" if HAVE_GL else "; ".join(reasons))


# ── шейдеры для moderngl (минимальный Lambert) ──
_VERTEX = """
#version 330
in vec3 in_position;
in vec3 in_normal;
uniform mat4 mvp;
uniform mat4 model;
out vec3 v_normal;
out vec3 v_pos;
void main() {
    gl_Position = mvp * vec4(in_position, 1.0);
    v_normal = mat3(model) * in_normal;
    v_pos = (model * vec4(in_position, 1.0)).xyz;
}
"""

_FRAGMENT = """
#version 330
in vec3 v_normal;
in vec3 v_pos;
uniform vec3 u_color;
uniform vec3 u_light;
out vec4 frag;
void main() {
    vec3 n = normalize(v_normal);
    float diff = max(dot(n, normalize(u_light - v_pos)), 0.0);
    float amb = 0.3;
    vec3 col = u_color * (amb + 0.7 * diff);
    frag = vec4(col, 1.0);
}
"""


def sphere_mesh(radius: float, seg: int = 24, rings: int = 16) -> tuple[list[float], list[int]]:
    """Vertices (x,y,z,nx,ny,nz) and UV sphere indices for GL."""
    verts: list[float] = []
    for r in range(rings + 1):
        phi = math.pi * r / rings
        for s in range(seg):
            theta = 2 * math.pi * s / seg
            x = radius * math.sin(phi) * math.cos(theta)
            y = radius * math.cos(phi)
            z = radius * math.sin(phi) * math.sin(theta)
            nx, ny, nz = x / radius, y / radius, z / radius
            verts.extend([x, y, z, nx, ny, nz])
    idx: list[int] = []
    for r in range(rings):
        for s in range(seg):
            a = r * seg + s
            b = r * seg + (s + 1) % seg
            c = (r + 1) * seg + s
            d = (r + 1) * seg + (s + 1) % seg
            if r != 0:
                idx.extend([a, b, d])
            if r != rings - 1:
                idx.extend([a, d, c])
    return verts, idx


def render_gl(
    bodies: list[dict],
    width: int = 640,
    height: int = 480,
    output: str = "frame_gl.png",
    bg: tuple[float, float, float] = (0.05, 0.09, 0.16),
) -> str:
    """Render spheres via moderngl (offscreen) → PNG (via custom encoder).

    bodies: [{position, radius, color:'#rrggbb'}]
    """
    if not HAVE_MODERNGL:
        raise ImportError("moderngl не установлен: " + availability_backend_gl()["reason"])
    import moderngl
    import numpy as np
    from render.pure_raster import (
        mat_look_at,
        mat_perspective,
        mat_mul,
        mat_translate,
        mat_scale,
    )

    ctx = moderngl.create_context(standalone=True, backend="egl")  # offscreen без X-сервера
    prog = ctx.program(vertex_shader=_VERTEX, fragment_shader=_FRAGMENT)
    fbo = ctx.simple_framebuffer((width, height))
    fbo.use()
    fbo.clear(*bg)

    if bodies:
        max_r = max(max(abs(c) for c in b["position"]) for b in bodies) or 1.0
    else:
        max_r = 1.0
    half = math.radians(50.0) / 2
    d = (max_r / max(math.sin(half), 1e-3)) * 1.35
    eye = (d * 0.55, d * 0.4, d * 0.75)
    el = math.sqrt(sum(c * c for c in eye)) or 1.0
    eye = tuple(c * d / el for c in eye)
    view = mat_look_at(eye, (0, 0, 0), (0, 1, 0))
    proj = mat_perspective(50.0, width / height, 0.05, 100.0)
    vp = mat_mul(proj, view)

    light = np.array([eye[0], eye[1] + max_r, eye[2]], dtype="f4")

    for b in bodies:
        verts, idx = sphere_mesh(b["radius"])
        vbo = ctx.buffer(np.array(verts, dtype="f4").tobytes())
        ibo = ctx.buffer(np.array(idx, dtype="i4").tobytes())
        vao = ctx.vertex_array(prog, [(vbo, "3f 3f", "in_position", "in_normal")], ibo)
        model = mat_mul(mat_translate(*b["position"]), mat_scale(1.0, 1.0, 1.0))
        mvp = mat_mul(vp, model)
        mvp_np = np.array(mvp, dtype="f4").T.tobytes()
        model_np = np.array(model, dtype="f4").T.tobytes()
        h = b.get("color", "#4fd1c5").lstrip("#")
        color = (int(h[0:2], 16) / 255, int(h[2:4], 16) / 255, int(h[4:6], 16) / 255)
        prog["mvp"].write(mvp_np)
        prog["model"].write(model_np)
        prog["u_color"].value = tuple(color)
        prog["u_light"].write(light.tobytes())
        vao.render(moderngl.TRIANGLES)

    # читаем пиксели и пишем PNG собственным кодером
    raw = fbo.read(components=3, alignment=1)
    # GL читает снизу вверх — переворачиваем строки
    row = width * 3
    flipped = bytearray()
    for y in range(height - 1, -1, -1):
        flipped += raw[y * row : (y + 1) * row]
    from render.png_codec import write_png

    write_png(output, flipped, width, height)
    return output

__link__("render.backend_gl", [('annotations', 'annotations'), ('math', 'math'), ('os', 'os'), ('Sequence', 'Sequence'), ('HAVE_GL', 'HAVE_GL'), ('availability', 'availability_backend_gl'), ('_VERTEX', '_VERTEX'), ('_FRAGMENT', '_FRAGMENT'), ('sphere_mesh', 'sphere_mesh'), ('render_gl', 'render_gl')])
