_LANG_REF = ["en"]  # интерфейс по умолчанию на английском; --lang ru вернёт русский


def set_lang(l: str) -> str:
    """Set interface language (ru | en)."""
    _LANG_REF[0] = l
    return l


def get_lang() -> str:
    """Current interface language."""
    return _LANG_REF[0]


def toggle_lang() -> str:
    """Toggle language ru ↔ en."""
    return set_lang("en" if get_lang() == "ru" else "ru")


def lang_label(l: str | None = None) -> str:
    """Short language label for footer."""
    return "РУС" if (l or get_lang()) == "ru" else "EN"


