def mode_title(item) -> str:
    """Mode name in interface language (item — dict menu_spec or ModeEntry)."""
    if isinstance(item, dict):
        name, base = item.get("name", ""), item.get("title", "")
    else:
        name, base = getattr(item, "name", ""), getattr(item, "title", "")
    if get_lang() == "en":
        return MODE_TITLES_EN.get(name, base)
    return base

_COLOR_MODE = "truecolor"  # truecolor | 256 | 16 | none
COLOR = True  # цветовой шлюз: отчёты всегда получают чистый текст


def detect_color_mode(stream=None) -> str:
    """Auto-detect terminal capabilities."""
    global _COLOR_MODE
    if os.environ.get("NO_COLOR"):
        _COLOR_MODE = "none"
        return _COLOR_MODE
    stream = stream or sys.stderr
    if not hasattr(stream, "isatty") or not stream.isatty():
        _COLOR_MODE = "none"
        return _COLOR_MODE
    term = os.environ.get("TERM", "")
    colorterm = os.environ.get("COLORTERM", "").lower()
    if colorterm in ("truecolor", "24bit") or "truecolor" in colorterm:
        _COLOR_MODE = "truecolor"
    elif "256color" in term:
        _COLOR_MODE = "256"
    elif term:
        _COLOR_MODE = "16"
    else:
        _COLOR_MODE = "none"
    return _COLOR_MODE


def color_on() -> None:
    """Handle color on."""
    global COLOR
    COLOR = True


def color_off() -> None:
    """Handle color off."""
    global COLOR
    COLOR = False


def _rgb_to_256(r: int, g: int, b: int) -> int:
    """Closest xterm-256 color."""
    best, best_d = 0, 1 << 30
    for i in range(256):
        if i < 16:
            rr, gg, bb = 0, 0, 0
        elif i < 232:
            n = i - 16
            rr = (n // 36) * 51
            gg = ((n // 6) % 6) * 51
            bb = (n % 6) * 51
        else:
            v = (i - 232) * 10 + 8
            rr = gg = bb = v
        d = (r - rr) ** 2 + (g - gg) ** 2 + (b - bb) ** 2
        if d < best_d:
            best, best_d = i, d
    return best


_ANSI16_FG = [
    (0, 0, 0), (205, 0, 0), (0, 205, 0), (205, 205, 0),
    (0, 0, 238), (205, 0, 205), (0, 205, 205), (229, 229, 229),
    (127, 127, 127), (255, 0, 0), (0, 255, 0), (255, 255, 0),
    (92, 92, 255), (255, 0, 255), (0, 255, 255), (255, 255, 255),
]


def _rgb_to_16(rgb) -> int:
    """Closest base ANSI color (30–37 / 90–97) for mode 16 (v2.2.0)."""
    best, best_d = 37, 1 << 30
    for i, (r, g, b) in enumerate(_ANSI16_FG):
        d = (rgb[0] - r) ** 2 + (rgb[1] - g) ** 2 + (rgb[2] - b) ** 2
        if d < best_d:
            best, best_d = (90 + i - 8) if i >= 8 else (30 + i), d
    return best


def _p3(rgb: tuple) -> str:
    """Do p3 for rgb and return the result."""
    if not COLOR or _COLOR_MODE == "none":
        return ""
    if _COLOR_MODE == "truecolor":
        return f"\x1b[38;2;{rgb[0]};{rgb[1]};{rgb[2]}m"
    if _COLOR_MODE == "256":
        return f"\x1b[38;5;{_rgb_to_256(*rgb)}m"
    return ""


def _c(rgb: tuple, bold: bool = False) -> str:
    """Do c for rgb, bold and return the result."""
    if not COLOR or _COLOR_MODE == "none":
        return ""
    if _COLOR_MODE == "16":
        return f"\x1b[1m\x1b[3{rgb and 0}m" if False else f"\x1b[{';'.join(['1'] if bold else [])}m"
    s = _p3(rgb)
    return f"\x1b[1m{s}" if bold else s


RESET_hud = "\x1b[0m" if COLOR else ""


def _col(rgb, bold=False):
    """General wrapper: color code or empty string (v2.2.0: mode 16 colors)."""
    if not COLOR or _COLOR_MODE == "none":
        return ""
    if _COLOR_MODE == "16":
        # v2.2.0: раньше возвращался "" (PALETTE_16 была мёртвой) — теперь
        # ближайший базовый ANSI-цвет по RGB-расстоянию
        code = _rgb_to_16(rgb)
        pre = "\x1b[1m" if bold else ""
        return f"{pre}\x1b[{code}m"
    s = _p3(rgb)
    if bold and s:
        s = "\x1b[1m" + s
    return s


# v2.2.0 (ИСПРАВЛЕНИЕ): раньше это были функции-обёртки _col(…), но код
# режимов передаёт имена палитры в colorize() как КОРТЕЖИ RGB — в цветном
# терминале colorize(text, cyn) падал с TypeError ('function' object is not
# subscriptable; вызовов как функций нет ни одного — проверено grep-ом).
# Теперь это кортежи, и все 57 мест вызова работают во всех режимах цвета.
cyn = ICE
grn = GRN
red = RED
ylw = GOLD
mag = VIO
blu = SKY
gry = GRY
wht = WHT
org = ORG
gold = GOLD


def reset() -> str:
    """Handle reset."""
    return "\x1b[0m" if (COLOR and _COLOR_MODE != "none") else ""


def colorize(text: str, rgb: tuple, bold: bool = False) -> str:
    """Wrap text with an ANSI truecolor escape for the given RGB."""
    code = _col(rgb, bold)
    if not code:
        return text
    return f"{code}{text}{reset()}"


def gradient_text(text: str, rgb_a: tuple, rgb_b: tuple) -> str:
    """Named color gradient interpolation (banner)."""
    if not COLOR or _COLOR_MODE == "none":
        return text
    n = max(len(text) - 1, 1)
    out = []
    for i, ch in enumerate(text):
        t = i / n
        rgb = tuple(int(a + (b - a) * t) for a, b in zip(rgb_a, rgb_b))
        out.append(_p3(rgb) + ch)
    out.append(reset())
    return "".join(out)


# ═══════════════════════════════════════════════════════════════════════════
# 2. Видимая ширина строки (пропуск ANSI-кодов)
# ═══════════════════════════════════════════════════════════════════════════
_ANSI_RE = None


def _strip_ansi(s: str) -> str:
    """Do strip ansi for s and return the result."""
    global _ANSI_RE
    if _ANSI_RE is None:
        import re

        _ANSI_RE = re.compile(r"\x1b\[[0-9;]*m")
    return _ANSI_RE.sub("", s)


def visible_width(s: str) -> int:
    """Do visible width for s and return the result."""
    return len(_strip_ansi(s))


def pad_to(s: str, width: int) -> str:
    """Do pad to for s, width and return the result."""
    vis = visible_width(s)
    if vis >= width:
        return s
    return s + " " * (width - vis)


def trunc_to(s: str, width: int) -> str:
    """Do trunc to for s, width and return the result."""
    if visible_width(s) <= width:
        return s
    return _strip_ansi(s)[: max(width - 1, 0)] + "…"


