# 4. Спиннер
# ═══════════════════════════════════════════════════════════════════════════
SPIN_FRAMES = "◐◓◑◒"
SPIN_BRAILLE = "⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏"


class Spinner:
    """Symbol spinner for undefined waits."""

    def __init__(self, label: str = "", stream=None, braille: bool = True):
        """Do Spinner.  init for label, stream, braille and return the result."""
        self.label = label
        self.stream = stream or sys.stderr
        self.frames = SPIN_BRAILLE if braille else SPIN_FRAMES
        self._i = 0
        self._t0 = time.time()
        self._active = False

    def frame(self, elapsed: float | None = None) -> str:
        """Do Spinner.frame for elapsed and return the result."""
        ch = self.frames[self._i % len(self.frames)]
        self._i += 1
        el = elapsed if elapsed is not None else time.time() - self._t0
        s = f"{colorize(ch, ICE, True)} {self.label} … {el:5.1f} с"
        return s if COLOR else f"[{ch}] {self.label} … {el:5.1f} с"

    def step(self) -> None:
        """Handle Spinner.step."""
        if _COLOR_MODE == "none" or not self.stream.isatty():
            return
        self.stream.write("\r" + pad_to(self.frame(), 78))
        self.stream.flush()


# ═══════════════════════════════════════════════════════════════════════════
# 5. Системный монитор (cpu · ram · temp · io-lat)
# ═══════════════════════════════════════════════════════════════════════════
class Monitor:
    """Lightweight system monitor: /proc directly, psutil — optional."""

    def __init__(self):
        """Handle Monitor.  init."""
        self._cpu_prev = None
        self._psutil = None
        try:
            import psutil  # noqa: F401

            self._psutil = psutil
        except ImportError:
            pass
        self.io_lat_us = None
        self._probe_io_latency()

    # ── cpu из /proc/stat ──
    @staticmethod
    def _read_proc_stat() -> tuple[int, int] | None:
        """Handle Monitor. read proc stat."""
        try:
            with open("/proc/stat", encoding="utf-8") as fh:
                parts = fh.readline().split()[1:]
            vals = [int(x) for x in parts]
            idle = vals[3] + (vals[4] if len(vals) > 4 else 0)
            return sum(vals), idle
        except (OSError, ValueError, IndexError):
            return None

    def cpu_pct(self) -> float:
        """Handle Monitor.cpu pct."""
        if self._psutil is not None:
            try:
                return self._psutil.cpu_percent(interval=None)
            except Exception:
                pass
        cur = self._read_proc_stat()
        if cur is None:
            return float("nan")
        if self._cpu_prev is None:
            self._cpu_prev = cur
            return 0.0
        dt = cur[0] - self._cpu_prev[0]
        di = cur[1] - self._cpu_prev[1]
        self._cpu_prev = cur
        if dt <= 0:
            return 0.0
        return max(0.0, min(100.0, 100.0 * (dt - di) / dt))

    # ── ram из /proc/meminfo ──
    @staticmethod
    def _read_meminfo() -> tuple[float, float]:
        """Handle Monitor. read meminfo."""
        try:
            info = {}
            with open("/proc/meminfo", encoding="utf-8") as fh:
                for line in fh:
                    k, _, v = line.partition(":")
                    info[k.strip()] = float(v.split()[0])  # кБ
            total = info.get("MemTotal", 0.0)
            avail = info.get("MemAvailable", info.get("MemFree", 0.0))
            return total / 1e6, avail / 1e6  # ГБ
        except (OSError, ValueError, IndexError):
            return 0.0, 0.0

    def ram(self) -> tuple[float, float]:
        """Handle Monitor.ram."""
        if self._psutil is not None:
            try:
                vm = self._psutil.virtual_memory()
                return vm.total / 1e9, vm.available / 1e9
            except Exception:
                pass
        return self._read_meminfo()

    # ── температура ──
    @staticmethod
    def temp_c() -> float:
        """Handle Monitor.temp c."""
        for zone in sorted(_list_dir("/sys/class/thermal")):
            try:
                with open(f"/sys/class/thermal/{zone}/temp") as fh:
                    return int(fh.read().strip()) / 1000.0
            except (OSError, ValueError):
                continue
        for hw in sorted(_list_dir("/sys/class/hwmon")):
            try:
                with open(f"/sys/class/hwmon/{hw}/temp1_input") as fh:
                    return int(fh.read().strip()) / 1000.0
            except (OSError, ValueError):
                continue
        return float("nan")

    # ── латентность пустого I/O-цикла ──
    def _probe_io_latency(self) -> None:
        """Handle Monitor. probe io latency."""
        import tempfile

        try:
            t0 = time.perf_counter()
            with tempfile.NamedTemporaryFile(mode="w+", delete=True) as fh:
                fh.write("x")
                fh.flush()
                fh.seek(0)
                fh.read()
            self.io_lat_us = (time.perf_counter() - t0) * 1e6
        except OSError:
            self.io_lat_us = None

    # ── строка для встраивания в бар ──
    def inline(self) -> str:
        """Handle Monitor.inline."""
        cpu = self.cpu_pct()
        tot, avail = self.ram()
        parts = [f"cpu {cpu:4.0f}%"]
        if tot > 0:
            parts.append(f"ram {tot - avail:.1f}/{tot:.1f}G")
        t = self.temp_c()
        if not math.isnan(t):
            parts.append(f"{t:.1f}°C")
        if self.io_lat_us is not None:
            parts.append(f"io {self.io_lat_us:.0f}мкс")
        return " · ".join(parts)


def _list_dir(path: str) -> list[str]:
    """Do list dir for path and return the result."""
    try:
        return [d for d in os.listdir(path) if d.startswith(("thermal_zone", "hwmon"))]
    except OSError:
        return []


# ═══════════════════════════════════════════════════════════════════════════
# 5b. HUD-монитор меню (v2.2.0): CPU/RAM/load/аптайм/N тел/движок.
#     Linux: /proc/stat, /proc/uptime, /proc/loadavg, /proc/meminfo;
#     на не-Linux — «n/a», не падаем.
# ═══════════════════════════════════════════════════════════════════════════
_HUD_MON = None


def _get_hud_mon() -> Monitor:
    """Lazy singleton Monitor for HUD menu."""
    global _HUD_MON
    if _HUD_MON is None:
        _HUD_MON = Monitor()
    return _HUD_MON


def _fmt_bytes_gb(gb: float) -> str:
    """Human-readable bytes from GB (decimal, as given by Monitor.ram)."""
    b = gb * 1e9
    if b < 1024:
        return f"{b:.0f} B"
    if b < 1024 ** 2:
        return f"{b / 1024:.1f} KiB"
    if b < 1024 ** 3:
        return f"{b / 1024 ** 2:.1f} MiB"
    if b < 1024 ** 4:
        return f"{b / 1024 ** 3:.2f} GiB"
    return f"{b / 1024 ** 4:.2f} TiB"


def _fmt_dur(s: float) -> str:
    """Duration: s → mm:ss → hh:mm → days."""
    if s < 60:
        return f"{s:.0f}s"
    if s < 3600:
        return f"{int(s // 60)}m{int(s) % 60:02d}s"
    if s < 86400:
        return f"{int(s // 3600)}h{int(s % 3600) // 60:02d}m"
    return f"{s / 86400:.1f}d"


def _uptime_s() -> float | None:
    """System uptime from /proc/uptime (None — not Linux)."""
    try:
        with open("/proc/uptime", encoding="utf-8") as fh:
            return float(fh.read().split()[0])
    except (OSError, ValueError, IndexError):
        return None


def _loadavg():
    """(1m, 5m, 15m) from /proc/loadavg (None — not Linux)."""
    try:
        with open("/proc/loadavg", encoding="utf-8") as fh:
            p = fh.read().split()
        return float(p[0]), float(p[1]), float(p[2])
    except (OSError, ValueError, IndexError):
        return None


def gauge(pct: float, width: int = 14) -> str:
    """Mini-bar: value 0..100, color by traffic light zones."""
    filled = max(0, min(width, int(round(pct / 100.0 * width))))
    col = TL_GREEN if pct < 55 else (TL_AMBER if pct < 80 else TL_RED)
    return colorize("█" * filled, col, True) + colorize("░" * (width - filled), INK_SOFT)


def hud_lines(app=None) -> list[str]:
    """Update and return 3 HUD lines (CPU | RAM | bodies/engine)."""
    mon = _get_hud_mon()
    cpu = mon.cpu_pct()
    tot, avail = mon.ram()
    up = _uptime_s()
    la = _loadavg()

    ram_str = "n/a" if tot <= 0 else (
        f"{_fmt_bytes_gb(tot - avail)} / {_fmt_bytes_gb(tot)}  "
        + gauge(100.0 * (tot - avail) / tot, 12)
    )
    up_str = "n/a" if up is None else _fmt_dur(up)
    la_str = "n/a" if la is None else f"{la[0]:.2f} {la[1]:.2f} {la[2]:.2f}"

    l1 = (
        colorize("  " + tr("hud.cpu") + " ", INK_SOFT) + gauge(cpu, 18) + " "
        + colorize(f"{cpu:5.1f}%", TL_AMBER, True) + "  "
        + colorize(tr("hud.load") + " ", INK_SOFT) + colorize(la_str, PAPER)
    )
    l2 = (
        colorize("  " + tr("hud.ram") + " ", INK_SOFT) + ram_str + "  "
        + colorize(tr("hud.uptime") + " ", INK_SOFT) + colorize(up_str, PAPER)
    )
    n_bodies = 0
    engine = "native_newton"
    if app is not None:
        sc = getattr(app, "scene", None)
        n_bodies = int(getattr(sc, "n", 0) or 0)
        engine = getattr(getattr(app, "config", None), "physics_engine", engine)
    l3 = (
        colorize("  " + tr("hud.bodies") + " ", INK_SOFT)
        + colorize(str(n_bodies), TL_GREEN, True) + "   "
        + colorize(tr("hud.engine") + " ", INK_SOFT)
        + colorize(engine, GOLD_B, True)
    )
    return [l1, l2, l3]


def draw_monitor(app=None, width: int = 80) -> None:
    """Render HUD: traffic light frame + three lines (menu command st)."""
    print()
    print(box_top(width, TL_AMBER))
    for line in hud_lines(app):
        print(box_row(line, width, TL_AMBER))
    print(box_bot(width, TL_AMBER))


# ═══════════════════════════════════════════════════════════════════════════
# 6. Прогресс-бар — одна строка, динамический, EMA-ETA
# ═══════════════════════════════════════════════════════════════════════════
def _term_width() -> int:
    """Handle term width."""
    try:
        w = shutil.get_terminal_size((80, 24)).columns
    except OSError:
        w = 80
    return max(30, min(w - 2, 100))


class ProgressBar:
    """
    Single-line dynamic progress bar (STDERR, repaint with \\r).

        ◐ Label ▰▰▰▰▱▱▱▱ 42.1% · status · cpu 87% · ETA 00:01:23 · up 00:00:12

    * EMA on progress rate — robust to uneven calculation phases;
    * for Non-TTY bars fade, milestone string printed every 10%;
    * thread-safe: one background pump thread for all updates.
    """

    def __init__(
        self,
        label: str = "",
        total: float = 100.0,
        stream=None,
        monitor: Monitor | None = None,
        eta_alpha: float = 0.22,
    ):
        """Do ProgressBar.  init for label, total, stream, monitor and return the result."""
        self.label = label
        self.total = max(total, 1e-12)
        self.stream = stream or sys.stderr
        self.monitor = monitor
        self.eta_alpha = eta_alpha
        self.enabled = (
            os.environ.get("TRIVORTEX_NO_PROGRESS", "") not in ("1", "true", "yes")
            and self.stream.isatty()
        )
        self.frac = 0.0
        self.tag = ""
        self._t0 = time.time()
        self._last_t = self._t0
        self._ema_rate = None  # доли/сек, EMA
        self._last_w = 0
        self._spin = Spinner("", stream=self.stream, braille=False)
        self._last_milestone = -1
        self._paused = False
        self._lock = threading.Lock()

    # ── публичное API ──
    def update(self, value: float, tag: str = "") -> None:
        """Do ProgressBar.update for value, tag and return the result."""
        with self._lock:
            now = time.time()
            frac = max(0.0, min(1.0, value / self.total))
            dt = now - self._last_t
            if dt > 0.01 and frac > self.frac:
                rate = (frac - self.frac) / dt
                if self._ema_rate is None:
                    self._ema_rate = rate
                else:
                    self._ema_rate = self.eta_alpha * rate + (1 - self.eta_alpha) * self._ema_rate
            self.frac = frac
            if tag:
                self.tag = tag
            self._last_t = now
            self._repaint(now)

    def narrow(self, lo: float, hi: float, value: float, tag: str = "") -> None:
        """Perspective projection (OpenGL-style, z in [-1,1])."""
        span = max(hi - lo, 1e-12)
        self.update(lo + span * max(0.0, min(1.0, value)), tag)

    def heartbeat(self) -> None:
        """Vertices and triangles of UV-sphere (poles along y)."""
        with self._lock:
            self._repaint(time.time())

    def pause(self) -> None:
        """Handle ProgressBar.pause."""
        self._paused = True

    def resume(self) -> None:
        """Handle ProgressBar.resume."""
        self._paused = False

    def finish(self, message: str = "") -> None:
        """Do ProgressBar.finish for message and return the result."""
        with self._lock:
            if self.enabled:
                line = colorize(f"  ✓ {self.label}", GRN, True) if COLOR else f"  [ok] {self.label}"
                if message:
                    line += " — " + message
                line += f"  ({self._fmt(time.time() - self._t0)})"
                self.stream.write("\r" + " " * self._last_w + "\r" + line + "\n")
                self.stream.flush()
            else:
                pass  # (unused local removed)
                if message:
                    print(f"  {self.label}: {message}")

    # ── внутреннее ──
    def _eta(self) -> float | None:
        """Handle ProgressBar. eta."""
        if self._ema_rate is None or self._ema_rate <= 1e-12:
            return None
        return max(0.0, (1.0 - self.frac) / self._ema_rate)

    @staticmethod
    def _fmt(sec: float) -> str:
        """Do ProgressBar. fmt for sec and return the result."""
        sec = int(sec)
        return f"{sec // 3600:02d}:{(sec % 3600) // 60:02d}:{sec % 60:02d}"

    def _repaint(self, now: float) -> None:
        """Do ProgressBar. repaint for now and return the result."""
        if not self.enabled or self._paused:
            return
        w = _term_width()
        pct = self.frac * 100.0
        spin = SPIN_BRAILLE[int(now * 10) % len(SPIN_BRAILLE)] if COLOR else "*"
        head = f"{colorize(spin, TL_AMBER, True)} {self.label}"
        bar_w = max(8, min(34, w // 3))
        filled = int(bar_w * self.frac)
        # v2.2.0: заполнение мультистоп-градиентом светофора (как в баннере)
        cells = [colorize("█", multistop((k + 0.5) / bar_w), True) for k in range(filled)]
        bar = "".join(cells) + colorize("░" * (bar_w - filled), INK_SOFT)
        line = f"{head} {bar} {pct:5.1f}%"
        # хвост: статус → монитор → ETA → up (усекается справа налево)
        tail_parts = []
        if self.tag:
            tail_parts.append(self.tag)
        if self.monitor is not None:
            try:
                tail_parts.append(self.monitor.inline())
            except Exception:
                pass
        eta = self._eta()
        if eta is not None:
            tail_parts.append(tr("pb.eta") + " " + self._fmt(eta))
        if self._ema_rate and self._ema_rate > 1e-12:
            tail_parts.append(f"{tr('pb.speed')} {self._ema_rate * self.total:.1f}/s")
        tail_parts.append("up " + self._fmt(now - self._t0))
        tail = " · ".join(p for p in tail_parts if p)
        budget = w - visible_width(line) - 3
        if tail:
            tail = trunc_to(tail, max(budget, 0))
            line = f"{line} · {tail}"
        line = trunc_to(line, w)
        self.stream.write("\r" + " " * self._last_w + "\r" + pad_to(line, w))
        self._last_w = visible_width(line)
        self.stream.flush()


class BarQueue:
    """Bounded cosmetic frame queue: frozen terminal doesn't deadlock
    calculation — old frames are simply discarded."""

    def __init__(self, maxsize: int = 256):
        """Do BarQueue.  init for maxsize and return the result."""
        import queue

        self.q: queue.Queue = queue.Queue(maxsize=maxsize)
        self._thread = None

    def put(self, fn) -> None:
        """Do BarQueue.put for fn and return the result."""
        try:
            self.q.put_nowait(fn)
        except Exception:
            pass  # очередь полна — выбрасываем самый старый кадр

    def start(self) -> None:
        """Handle BarQueue.start."""
        if self._thread is not None:
            return

        def pump():
            while True:
                fn = self.q.get()
                if fn is None:
                    return
                try:
                    fn()
                except Exception:
                    pass

        self._thread = threading.Thread(target=pump, daemon=True)
        self._thread.start()

    def stop(self) -> None:
        """Handle BarQueue.stop."""
        self.put(None)


# ═══════════════════════════════════════════════════════════════════════════
# 7. Контрольный файл .tv_ctl (внешнее управление баром)
# ═══════════════════════════════════════════════════════════════════════════
def ctl_command(run_dir: str) -> str | None:
    """Reads pause/resume/snapshot commands from <run_dir>/.tv_ctl."""
    path = os.path.join(run_dir, ".tv_ctl")
    try:
        with open(path, encoding="utf-8") as fh:
            cmd = fh.read().strip().lower()
        if cmd in ("pause", "resume", "snapshot"):
            os.remove(path)
            return cmd
    except OSError:
        pass
    return None


