# Глобальное состояние приложения
# ═══════════════════════════════════════════════════════════════════════════
class App_trivortex_master:
    """Radius encoded by symbol density + spot size: r_px < 1 — single"""

    def __init__(self):
        """Handle App_trivortex_master.  init."""
        self.config = resolve_paths(from_profile("standard"), ROOT)
        self.scene = None
        self.last_sim = None
        self.last_charts: list[str] = []
        self.last_reports: dict[str, str] = {}
        self.runs_dir = os.path.join(ROOT, "runs")
        os.makedirs(self.runs_dir, exist_ok=True)
        self.session_log = os.path.join(
            self.runs_dir, f"session_{_dt.datetime.now().strftime('%Y%m%d_%H%M%S')}.log"
        )
        self._log("сессия начата")

    def _log(self, msg: str) -> None:
        """Do App_trivortex_master. log for msg and return the result."""
        try:
            with open(self.session_log, "a", encoding="utf-8") as fh:
                fh.write(f"{_dt.datetime.now().isoformat(timespec='seconds')}" f"  {msg}\n")
        except OSError:
            pass

    def new_run_dir(self, tag: str) -> str:
        """Do App_trivortex_master.new run dir for tag and return the result."""
        d = os.path.join(self.runs_dir, f"run_{tag}_{_dt.datetime.now().strftime('%Y%m%d_%H%M%S')}")
        os.makedirs(d, exist_ok=True)
        return d

    def require_scene(self):
        """Handle App_trivortex_master.require scene."""
        if self.scene is None:
            print(colorize("\n  сцена не создана — сначала пункт 1 (Лаборатория)", org))
            return None
        return self.scene


